pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins tightly packed.
    // We use a quadratic penalty for the remaining space to discourage inefficient "gaps".
    score += (post_residual as f64).powi(2) * 0.05;

    // 2. Lookahead Synergy: If the next item fits into the current post_residual,
    // strongly incentivize this bin to minimize the creation of new bins later.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 15.0;
    }

    // 3. New Bin Thresholding: If this is the only bin that fits the item,
    // we heavily penalize opening a new bin by artificially inflating the score
    // of the empty bin relative to the existing fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 200.0;
        } else {
            // If no other bins fit, prioritize the new bin but apply a slight tax 
            // based on how many bins are already open to discourage fragmentation.
            score += (open_bins_count as f64) * 2.0;
        }
    }

    // 4. Mean Residual Balancing: If the post_residual is significantly better than 
    // the current global mean, we favor this bin to keep the system state consistent.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 2.5;
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive 
    // about filling bins to avoid leaving stragglers in many half-empty bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base score: prioritize Best-Fit (smaller post_residual is better)
    // We add a penalty for empty bins to force usage of existing ones unless the fit is terrible.
    let mut score = post;

    // If bin is empty, apply a "startup cost" that decreases as we approach the end of the stream
    // to encourage consolidation in the final stages.
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress);
    }

    // Lookahead logic: if the next item is large, penalize small post_residuals that leave
    // insufficient space (e.g., < 15) for the next item.
    if next_item_size > 0 {
        let gap_penalty = if post < next_item_size as f64 && post > 0.0 {
            (next_item_size as f64 - post).powi(2) * 0.5
        } else {
            0.0
        };
        score += gap_penalty;
    }

    // Penalty for creating "dead space": if post_residual is small but > 0, it's often 
    // worse than leaving it empty or filling it perfectly.
    if post > 0.0 && post < 10.0 {
        score += 20.0 * (1.0 - post / 10.0);
    }

    // Normalize against mean_residual to prevent scattering items across too many bins
    // if the current bin is significantly "emptier" than the average, favor it.
    if residual > mean_residual {
        score -= (residual - mean_residual) * 0.2;
    }

    // If this is the only fitting bin, heavily discount it to force usage and avoid new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small gaps that are likely to become unusable.
    // We define "unusable" as < 10 (since the minimum item size is 10).

    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (gaps smaller than the smallest possible item).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open bins pressure: If this is an existing bin, penalize it if we have too many open bins,
    // unless this bin is a "Best Fit" (post_residual is very small).
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 0.5;

        // Reward bins that have residuals close to the mean to keep them balanced
        let diff_from_mean = (post_residual as f64 - mean_residual).abs();
        score += diff_from_mean * 0.1;
    } else {
        // Penalty for opening a new bin: only open if the current fitting options are poor.
        score += 15.0;
    }

    // 4. Critical threshold: If this is the only bin that fits the item, make it very attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: prioritize tightness (Best-Fit)
    let mut score = post;

    // Penalty for creating 'dead space' that is too small for common items (below 10)
    // We penalize post_residual values that are likely to be unusable.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: If the next item can fit in the current residual, 
    // prioritize keeping this bin open for that future item.
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= (next_item_size as f64) * 0.5;
    }

    // Dynamic scaling based on stream progress:
    // As we approach the end of the stream, prioritize closing bins (lower residual)
    // to avoid leaving fragmented space at the very end.
    let end_game_pressure = progress * 20.0;
    score += post * end_game_pressure;

    // If this is a new bin, apply a threshold penalty to prevent opening 
    // new bins unless the fit in existing bins is truly abysmal.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high.
        // We reduce this cost slightly as open_bins_count increases to allow for better packing.
        let new_bin_base_cost = 45.0 - (open_bins_count as f64 * 0.5);
        score = new_bin_base_cost;
    } else {
        // Influence of mean_residual: If current bin is significantly better 
        // than the average, reward it.
        if (post_residual as f64) < mean_residual {
            score -= (mean_residual - post) * 0.2;
        }
    }

    // Ensure we don't return negative scores that might confuse logic, 
    // though the relative ordering is what matters.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to prioritize tight packing.
    // 2. New-Bin Thresholding: Only open a new bin if the current fit is extremely poor
    //    or if we are forced to (using fitting_bins_count).
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin to discourage it unless necessary.
        score = 45.0; 

        // If the item is large, opening a new bin is less penalized.
        score -= (item_size as f64) * 0.4;
    } else {
        // Penalty for creating a "fragment" that cannot fit the next item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }

        // Reward placements that bring the bin residual closer to the global mean residual,
        // which helps keep bin states uniform and reduces variance.
        let diff_from_mean = (post_residual as f64 - mean_residual).abs();
        score += diff_from_mean * 0.2;

        // If this is the only bin that can fit the item, prioritize it strongly
        // to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Progression awareness: As we approach the end of the stream,
    // be more aggressive about filling existing bins (don't leave space).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: Heavily penalize residuals that are too small to fit typical subsequent items.
    // If post_residual is in the range [1, 9], it is highly likely to be wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open bins pressure: If this is an existing bin (not a new one), penalize it 
    // proportional to the number of open bins to favor packing tighter into fewer bins.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 2.0;
    } else {
        // If this is a new bin, penalize based on the progress of the stream.
        // Opening a new bin early is expensive; opening it late is more acceptable.
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 * (1.0 - progress);
    }

    // 4. Fitting constraint: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Mean residual balancing: Prefer bins that keep the global mean residual closer to 
    // the target bin_residual to maintain uniform packing density.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit principle).
    // Penalize gaps that are too small to fit typical future items (e.g., < 20).
    let mut score = post;

    if post < 20.0 && post > 0.0 {
        score += 20.0 - post;
    }

    // Lookahead coupling: If next_item_size exists and doesn't fit, penalize the current choice
    // to preserve space for the upcoming item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Stream progression weighting: As we approach the end of the stream, 
    // prioritize closing bins (lower post_residual) to reduce waste.
    score += (1.0 - progress) * (mean_residual - post).abs();

    // Strategy for new bins:
    // Only open a new bin if the current fit is extremely poor (large waste).
    if bin_residual == bin_capacity {
        // This is the new bin candidate. 
        // We only return a low score if the average residual is already high 
        // or if we are at the end of the stream and need to pack efficiently.
        score = 45.0 + (progress * 10.0);
    } else {
        // If this bin is the last chance for this item (fitting_bins_count == 1),
        // heavily reward taking this bin to prevent opening a new one.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
