    let dead_space_penalty = if post < 10.0 {
        (10.0 - post).powf(1.5) * (1.0 + progress)
    } else {
        0.0
    };

    // Reward bins that tightly fit the current item relative to the mean residual
    // to encourage bin consolidation (Best Fit logic).
    let fit_efficiency = (post - mean_residual).powi(2);

    // Lookahead: If the next item is large, favor bins that have enough space left 
    // to accommodate it, preventing premature bin opening later.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post).powf(1.2) * (1.0 - progress)
    } else {
        0.0
    };

    // If this is a new bin (residual == capacity), apply a dynamic cost.
    // We only open a new bin if the cost of placing in existing bins is higher.
    let new_bin_base_cost = 45.0 + (progress * 20.0);
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = if is_new_bin {
        new_bin_base_cost
    } else {
        post + dead_space_penalty + fit_efficiency + lookahead_penalty
    };

    // If this is the only bin that can fit the item, prioritize it to avoid 
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

