pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a 'sliver' (small unusable space)
    // Residuals < 10 are often dead weight unless they fit very small items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Encourage Best-Fit: penalize larger post-residuals to keep bins tightly packed.
    // However, harmonize with the next item to prevent fragmentation.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit reward
            if post_residual == next_item_size {
                score -= 40.0;
            }
            // Good fit reward (leaving just enough for next item)
            score -= (next_item_size as f64) * 0.5;
        } else {
            // Penalty if this bin cannot accommodate the lookahead item
            score += 20.0;
        }
    }

    // Harmonic Class logic: avoid bin sizes that are awkward fractions of capacity
    // 100/3 = 33, 100/4 = 25, 100/5 = 20. Residuals near these values are versatile.
    let remainder_mod = post_residual % 20;
    if remainder_mod == 0 {
        score -= 10.0;
    }

    // Discourage opening new bins unless necessary (fitting_bins_count == 0)
    // If the bin is new, impose a high base cost unless it's the only option.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 65.0; // Heavy penalty for wasting a bin slot
        } else {
            score -= 10.0; // Reward for necessity
        }
    }

    // Progression adjustment: be more aggressive in packing as we approach the end
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but non-zero (fragments)
    // if they cannot accommodate the lookahead item.
    if post_residual > 0 && post_residual < next_item_size {
        score += 45.0;
    }

    // 2. Bin Preservation: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 3. Fragmentation avoidance: If we are creating a small gap, check if it's 
    // a "harmonic trap". 100 is the capacity, we favor residuals that are multiples 
    // of common item sizes (e.g., 20, 25, 50).
    if post_residual > 0 && post_residual < 20 {
        score += 20.0;
    }

    // 4. Lookahead coupling: If current item + next item fits perfectly, 
    // reward this bin significantly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        // Reward tighter fits for the lookahead
        score -= (100.0 - leftover as f64) * 0.1;
    }

    // 5. New Bin Logic: Discourage opening a new bin unless the current 
    // fitting options are extremely poor (i.e., high residual).
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low,
        // suggesting we are "crowding" existing bins too much.
        if mean_residual > 25.0 {
            score -= 10.0; 
        } else {
            score += 50.0;
        }
    }

    // 6. Progress scaling: As we reach the end of the stream, prioritize 
    // closing bins (lower residual) over spreading items out.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large residuals (standard Best Fit).
    // The base score is already post_residual, which inherently favors tighter fits.

    // 2. Lookahead Synergy: If the post_residual can perfectly (or near-perfectly) 
    // accommodate the next item, reward this placement heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= (100.0 - slack) * 1.5;
        } else {
            // Penalty if the current placement prevents the next item from fitting
            // in this bin, forcing a new bin for the next item.
            score += 20.0;
        }
    }

    // 3. Global Efficiency: If this is the last fitting bin, avoid leaving a 
    // very small gap (the "fragmentation trap") unless it's a near-perfect fit.
    if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Distribution Balancing: Penalize opening a new bin if the current 
    // mean_residual is already high (suggesting under-utilization).
    if bin_residual == bin_capacity {
        score += mean_residual * 0.8;

        // Dynamic threshold for opening new bins based on stream progress.
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 10.0;
    }

    // 5. Aggressive Packing: Penalize bins that deviate significantly from 
    // the current mean residual to keep bins at similar fill levels.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    // We want to minimize wasted space, so lower post_residual is better.
    let mut score = post;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize residuals in the range [1, 15] heavily as they are hard to fill.
    if post > 0.0 && post < 16.0 {
        score += (16.0 - post) * 5.0;
    }

    // Lookahead logic: if the next item is large, favor bins that leave enough room for it.
    // If post_residual is smaller than the next item, we penalize the current choice.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 2.5;
        }
    }

    // Dynamic thresholding: as we reach the end of the stream, prioritize packing 
    // tightly to avoid opening new bins.
    let exhaustion_factor = 1.0 - progress;
    score += (open_bins_count as f64) * exhaustion_factor * 2.0;

    // If this is an empty bin (new bin candidate), apply a high base penalty.
