        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless the fit is excellent.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless the item is large, in which case it is justified.
    if bin_residual == bin_capacity {
        score += 45.0 - (item_size as f64 * 0.4);
    }

    // 3. Lookahead Sensitivity: If the next item is large, prioritize keeping 
    // a larger residual in the current bin to accommodate it.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 20.0;
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // strongly favor it to prevent unnecessary new bin openings.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Efficiency: Penalize the growth of open_bins_count relative to progress.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 + progress * 2.0);

    // 6. Mean Residual Balancing: Penalize bins that deviate significantly from the mean 
    // to keep the bin distribution uniform.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

