    // "dead space" that is too small to fit common items (e.g., < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; 
    }

    // 2. Lookahead Logic: If the next item fits into the current post_residual, 
    // significantly lower the score to encourage "perfect packing" of pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Harmonic Pressure: Use modulo arithmetic to favor bin states 
    // that align with fractions of capacity (e.g., 1/2, 1/3, 1/4).
    let harmonic_penalty = (post_residual % 25) as f64 * 0.5;
    score += harmonic_penalty;

    // 4. Open Bin Management: If this is the last fitting bin, strongly prefer 
    // it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. New Bin Thresholding: Penalize opening a new bin unless the 
    // current bin residual is extremely poor for the incoming item.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the mean residual is high enough to 
        // suggest we are wasting space in existing bins.
        if mean_residual < 20.0 {
            score += 50.0; // Discourage new bin
        } else {
            score -= 10.0; // Accept new bin if existing ones are inefficient
        }
    }

    // 6. Progression Weighting: As the stream nears the end, be more aggressive
    // about using existing bins to avoid leftover bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize small gaps that are too small to hold any likely future items (under 10).
    // If post_residual is in the "danger zone" (1..9), add a massive penalty to discourage this choice.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item can fit in the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when existing ones are available.
    // If this is a new bin (bin_residual == bin_capacity) and we have other fitting options, increase score.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Mean Residual Balancing: Favor bins that keep the mean residual closer to the ideal half-full state (50).
    // This helps in keeping the distribution of space usage uniform.
    let current_mean_impact = (post_residual as f64 - 50.0).abs();
    score += current_mean_impact * 0.1;

    // 5. Efficiency Scaling: As the stream progresses, prioritize tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin:
    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    // We penalize it based on how many existing bins could have fit the item.
    if bin_residual == bin_capacity {
        score += 45.0 + (fitting_bins_count as f64 * 15.0);
    }

    // 2. Lookahead matching:
    // Reward bins where the post_residual is close to the next_item_size.
    // This minimizes future fragmentation by creating "perfect" fits.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;

        // If post_residual is slightly too small for the next item, penalize heavily.
        if post_residual < next_item_size {
            score += 25.0;
        }
    }

    // 3. Fragmentation control:
    // Penalize creating bins that are slightly below the mean residual of existing bins,
    // as these are likely to be "stranded" space.
    if (post_residual as f64) < mean_residual {
        score += (mean_residual - post_residual as f64) * 0.5;
    }

    // 4. Density preference:
    // Favor bins that leave smaller residuals (Best-Fit principle).
    // The base score (post_residual) already accounts for this, but we amplify it.
    score += (post_residual as f64) * 0.2;

    // 5. Progression adjustment:
    // As we approach the end of the stream, be more aggressive about filling existing bins
    // to avoid leaving partially filled bins at the end.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // Penalty is high for large post_residuals (wasted space).
    score += (post_residual as f64).powf(1.2);

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. New-Bin Thresholding: Prevent opening a new bin prematurely.
    // If we are considering a new bin (bin_residual == bin_capacity), apply a heavy 
    // penalty unless the number of currently fitting bins is very low.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Gradually reduce the penalty for opening a new bin as the stream progresses,
            // but keep it high relative to tight fits.
            score += (100.0 - (progress * 20.0)) + (fitting_bins_count as f64 * 10.0);
        }
    } else {
        // 4. Global State Awareness: If this bin is significantly "emptier" than the average,
        // penalize it to encourage filling the tighter bins first.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        if bin_residual as f64 > mean_residual {
            score += deviation * 0.5;
        }
    }

    // 5. Critical Pressure: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin heavily, especially as the stream progresses
    // (A new bin is identified when bin_residual == bin_capacity)
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 
        (1.0 - progress) * 45.0 + 15.0 
    } else { 
        0.0 
    };

    // Best-fit/Worst-fit balancing:
    // We want to minimize post_residual (Best Fit), but we penalize 
    // leaving a very small, unusable gap (e.g., 1-5 units) 
    // using a non-linear exponential penalty.
    let gap_penalty = if post < 6.0 && post > 0.0 {
        (6.0 - post).powi(2) * 5.0
    } else {
        0.0
    };

    // Lookahead logic: If the next item exists, reward bins that leave 
    // enough space for it (post_residual >= next_item_size).
    let lookahead_reward = if next_item_size > 0 && post >= next_item_size as f64 {
        -12.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Encourage filling bins that are already "half-empty" to keep the 
    // distribution of residuals uniform.
    let residual_balance = (post - mean_residual).abs() * 0.1;

    // Final score: prioritize lower values.
    // Base score is post_residual (Best Fit principle) + penalties/rewards.
    post + gap_penalty + new_bin_penalty + lookahead_reward + residual_balance
}

