    let mut score = post;

    // Penalty for opening a new bin: significantly higher if there are still fitting bins
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0 * (1.0 - progress);
    }

    // Lookahead logic: if next_item_size is large, avoid creating small residuals now
    if next_item_size > 0 {
        let next_val = next_item_size as f64;
        // If the current post_residual is too small to fit the next item, penalize it quadratically
        if (post_residual as u32) < next_item_size {
            score += (next_val - post).powf(1.5);
