    // Coupling with mean_residual: avoid bins that deviate significantly from average density
    // This helps in keeping bin fill levels balanced
    let density_deviation = (post - mean_residual).abs();
    score += density_deviation * 0.5;

    // Final scaling: favor bins that are nearly full towards the end of the stream
    // to minimize the number of trailing open bins
    score -= (1.0 - post / bin_capacity as f64) * progress * 20.0;

