        // Global progress scaling: Opening new bins is more expensive late in the stream
        score += (step_index as f64 / total_items as f64) * 10.0;
    }

    // 5. Non-linear thresholding:
    // Heavily penalize "dead zones" where the residual is too small for any likely item (e.g., 1-9)
    if post_residual > 0 && post_residual < 10 {
