pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the post_residual, but prioritize bins that can accommodate the next_item_size.
    // If post_residual is exactly next_item_size, we reward it heavily (perfect 2-step fit).
    // We penalize opening new bins unless the current options are very poor (high post_residual).

