            // If mean_residual is low, opening a new bin is an inefficient waste of space
            score += 40.0 + (mean_residual * 0.5);
        }
    } else {
        // 3. Favor bins that bring the residual closer to the global mean (balancing)
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;

        // 4. Critical threshold: If this is the only bin that fits the item, make it very attractive
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 5. Progression scaling: As we approach the end of the stream, be more conservative with bin usage
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

