pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the "New Bin" choice (residual == capacity) to force filling existing bins early.
    // As progress approaches 1.0 (end of stream), the penalty for new bins decreases to allow cleanup.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 50.0 + 10.0
    } else {
        0.0
    };

    // Calculate how well the current item fits relative to the mean residual of all open bins.
    // Lower score is better: prioritize bins that leave the smallest residual (Best Fit).
    // We add a non-linear interaction: if we are late in the stream, we penalize bins that 
    // leave "unusable" small gaps (e.g., < 10) more aggressively, unless they fit the next item.
    let gap_penalty = if post < 10.0 && post > 0.0 {
        (1.0 + progress) * 15.0
    } else {
        0.0
    };

    // Lookahead logic: Reward bins that leave exactly enough room for the next item.
    let next_item_bonus = if next_item_size > 0 && post >= next_item_size as f64 && post < (next_item_size as f64 + 5.0) {
        -25.0 * (1.0 - progress * 0.5)
    } else {
        0.0
    };

    // Coupling: Combine post_residual with the state of the system.
    // We use a polynomial weight on post_residual to favor tight packing.
    let base_score = post.powf(1.2);

    // Final score assembly
    base_score + new_bin_penalty + gap_penalty + next_item_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
