    // based on progress to allow more flexibility as the stream nears completion.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        // Base penalty, decreasing slightly as we reach the end of the stream
        // to prevent leaving too many bins under-filled at the very end.
        (bin_capacity as f64) * 1.5 * (1.0 - 0.2 * progress)
    } else {
        0.0
    };

    // Best-Fit Decreasing (BFD) core: lower post_residual is better.
    // We penalize small residues that are too small to fit common items (10-20 range).
    // A quadratic penalty on small residues helps avoid "shards" of unusable space.
    let shard_penalty = if post_res < 15.0 && post_res > 0.0 {
        (15.0 - post_res).powi(2) * 0.5
    } else {
        0.0
    };

    // Lookahead: If the next item is large, prioritize keeping the current bin's
    // post_residual large enough to accommodate it.
    let lookahead_penalty = if next_item_size > 0 && post_res < next_item_size as f64 {
        (next_item_size as f64 - post_res) * 2.0
    } else {
