    };

    // Influence of mean_residual: if current bin is better than average, prioritize it.
    let efficiency_bonus = (post_res - mean_residual) * 0.1;

    // Final score combination:
    // We want to minimize the score, so penalties are added and bonuses are subtracted.
    let score = post_res + new_bin_penalty + shard_penalty + lookahead_penalty + efficiency_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
