    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Bin Density Balancing: If we have many open bins, penalize opening a new one 
    // or using a bin that keeps the mean_residual high.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have existing capacity.
        score += (open_bins_count as f64) * 12.0;
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Favor bins that keep the overall mean_residual low to maintain flexibility.
        if (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 4. Tight Fit Reward: If we hit a perfect fit, reward it significantly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // 5. Progress-based Pressure: As we reach the end of the stream, 
    // prioritize closing existing bins over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Encourage Best-Fit: Lower post_residual is generally better.
    // Penalty for leaving large gaps that are likely unusable.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.2);
    }

    // 2. Lookahead Integration: If the next item fits into the post_residual, 
    // significantly reward this placement to chain items together.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Prevent Fragmentation: Penalize cases where we leave space smaller than the mean_residual
    // of other bins, as those gaps are statistically harder to fill.
    if (post_residual as f64) < mean_residual && post_residual > 0 {
        score += mean_residual - (post_residual as f64);
    }

    // 4. New Bin Logic: If this is an empty bin, only pick it if we have no 
    // good existing fits. We set a threshold cost for opening new bins 
    // based on the current capacity utilization.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have many open bins already, 
        // to prevent premature bin opening.
        score += 45.0 + (open_bins_count as f64 * 0.5);
    } else {
        // If this is the last chance for this item in existing bins, 
        // heavily reward it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 5. Progression awareness: As the stream nears the end, be more aggressive
    // about filling existing bins to reduce the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Minimize post_residual (Best-Fit principle)
    // We favor bins where post_residual is small, but penalize tiny "slivers" (1-5) 
    // that are unlikely to accommodate future items.
    if post_residual > 0 && post_residual <= 5 {
        score += 25.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // we reward this placement heavily to keep bins packed tightly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Dynamic New-Bin Threshold:
    // As the stream progresses, make it harder to open new bins unless the current
    // fit is objectively poor (e.g., leaving a large, inefficient gap).
    if is_new_bin {
        // Base penalty for opening a new bin
        score += 45.0;

        // Dynamic scaling: opening a new bin becomes costlier as we approach the end
        // of the stream to force tighter packing of remaining items.
        score += progress * 30.0;

        // If we have many open bins already, we should prefer filling existing ones.
        score += (open_bins_count as f64) * 2.0;
    } else {
        // 4. Global State Awareness:
        // If the current bin's residual is significantly better (larger) than the 
        // global mean residual, we penalize it to avoid "hoarding" space in one bin
        // while others remain fragmented.
        if (bin_residual as f64) > mean_residual + 15.0 {
            score += 10.0;
        }
    }

    // 5. Critical Pressure:
    // If this is the only bin that can fit the item, we lower the score 
    // to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    // We want to minimize post_residual, so lower values are naturally better.
    let mut score = post;

    // Penalty for creating a bin that is too empty (near 100) if we are early in the stream.
    // This discourages opening new bins too aggressively.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress).powf(0.5);
    }

    // Lookahead logic: if the next item is large and this bin has little space left,
    // we penalize this bin to force it to take smaller items if possible.
    if next_item_size > 0 {
        let tightness = (next_item_size as f64) / (post + 1.0);
        score += tightness * 15.0;
    }

    // Dynamic adjustment based on current bin density.
    // If the mean residual is high, we are being too loose; prioritize filling bins.
    score += (mean_residual / bin_capacity as f64) * 10.0;

    // Favor bins that have fewer fitting options for the current item to keep "flexible" bins open.
    if fitting_bins_count > 0 {
        score += (fitting_bins_count as f64).ln() * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We prioritize bins that result in residuals that are either 0 (perfect fit) 
    // or large enough to accommodate common item sizes.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (1.0 - (post_residual as f64 / 20.0));
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // we heavily favor this bin to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 55.0;
    }

    // Heuristic for new bin creation:
    // Only open a new bin if the current fit is extremely poor (post_residual < 10)
    // or if we are forced to (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0; // High penalty for opening a new bin if an existing one fits
        } else {
            score -= 20.0; // Moderate incentive if we have no choice
        }
    }

    // Harmonic class logic: favor residuals that align with common item size increments.
    // Penalize odd residuals that are "awkward" (e.g., 17, 23).
    let rem = post_residual % 10;
    if rem > 0 && rem < 5 {
        score += 5.0;
    }

    // Global state awareness: If we have many open bins, prioritize closing them 
    // by filling them to capacity (low post_residual).
    score += (open_bins_count as f64) * 0.5;

    // Progress scaling: As the stream nears the end, prioritize tight packing 
    // to minimize the impact of the final few items.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is in the "unusable" range (1-9), 
