    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Integration: If the next item is large (e.g., > 50), 
    // try to keep post_residual large enough to accommodate it.
    if next_item_size > 50 && post_residual < next_item_size {
