    // 4. Tight Fit Reward: If the item fits exactly, reward it to minimize entropy.
    if post_residual == 0 {
        score -= 10.0;
    }

    // 5. Progression Scaling: As we approach the end of the stream, 
    // prioritize filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity && progress > 0.8 {
