    // of the capacity to maximize future item compatibility.
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for common items (e.g., < 10)
    // Small residuals are often unusable; we prefer to leave them larger or zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead coupling: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than the next item, we penalize the current placement.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 3. Harmonic alignment: Favor residuals that are multiples of 20 (factors of 100).
    // This keeps the remaining space "clean" for future items.
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

    // 4. Scarcity management: If only one bin can fit this item, force its use to avoid new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Global state normalization: Penalize opening new bins as the stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 + (progress * 20.0);
    }

    // 6. Mean residual balancing: Penalize bins that deviate significantly from the average.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
