    // 2. Lookahead mechanism: Reward bins that can accommodate the next item perfectly
    // or keep the residual small enough to act as a buffer.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit reward
            score -= (100.0 - (post_residual - next_item_size) as f64).sqrt() * 5.0;
        } else {
