            score += next_item_size as f64 * 2.0;
        }
    }

    // 3. Pressure management: If we are near the end of the stream, prioritize tight packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    // 4. Mean residual alignment: Avoid bins that deviate significantly from the current average density.
    // This promotes uniform filling across all open bins.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // 5. New bin logic adjustment:
    // If this is a new bin (bin_residual == bin_capacity), make it expensive unless
    // fitting_bins_count is 0 or all open bins result in very poor residuals.
    if bin_residual == bin_capacity {
        // High base cost to open a new bin, reduced by the number of currently open bins
        // to prevent excessive fragmentation.
        score += 85.0 - (open_bins_count as f64 * 0.5);
    } else {
        // Prefer existing bins, but penalize if the fitting bin is the 'last chance' 
        // to pack into a bin that would otherwise be left under-utilized.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
