pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize empty bin creation heavily early on, but allow more flexibility as the stream ends.
    // This is the "New Bin Penalty" factor.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 
        (15.0 - (progress * 10.0)) + (open_bins_count as f64 * 0.5) 
    } else { 
        0.0 
    };

    // Calculate "Tightness" score: punish post_residual for being too small (fragmentation) 
    // or too large (wasted space). Optimal is usually low but non-zero to allow future fits.
    // We use a quadratic penalty centered around 15% of bin_capacity.
    let target_residual = 15.0;
    let tightness_penalty = ((post - target_residual).powi(2)) * 0.1;

