    } else {
        0.0
    };

    // Reward bins that are closer to the mean residual to keep bin usage density uniform.
    let uniformity_bonus = (post - mean_residual).abs() * 0.2;

    // Final score: Lower is better.
    post + new_bin_penalty + tightness_penalty + lookahead_penalty + uniformity_bonus
}

