    }

    // 3. Penalty for opening a new bin:
    // If this is a new bin (residual == capacity), penalize based on how many
    // fitting bins are available. If fitting_bins_count > 0, we should rarely open a new bin.
    if bin_residual == bin_capacity {
        score += 35.0 + (fitting_bins_count as f64 * 15.0);

        // As we approach the end of the stream, be more conservative about opening new bins
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 4. Global state coupling:
    // If the mean residual of open bins is high, we are already fragmenting too much.
    // Discourage creating more bins if the current average is already quite high.
    if mean_residual > 30.0 && bin_residual == bin_capacity {
        score += 25.0;
    }

    // 5. Critical Threshold:
    // If post_residual is very small (< 5), it's a "perfect fit" (Best-Fit variant).
    // Reward this to minimize fragmentation.
    if post_residual < 5 {
        score -= 20.0;
    }

    // 6. Penalty for "dangerous" residuals:
    // Residuals between 5 and 15 are often hard to fill later. Penalize them.
    if post_residual >= 5 && post_residual < 15 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

