    let mut score = post;

    // Penalty for creating "dead zones" (small residuals that are hard to fill).
    // We penalize residuals in the (0, 10) range heavily, as they are likely wasted.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: if the next item fits into this post_residual, 
    // we reward this bin significantly to encourage packing pairs.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 40.0 * (1.0 - progress);
    }

    // Dynamic thresholding: as the stream progresses, we become more conservative 
    // about opening new bins. We penalize the "New Bin" candidate (bin_residual == bin_capacity)
    // increasingly as we approach the end of the stream.
    if bin_residual == bin_capacity {
        score += 30.0 + (progress * 50.0);
    }

    // Encourage filling bins that are already "half-empty" compared to the global mean,
    // balancing the load across active bins to keep options open.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // If this is the last chance to fit the item into an existing bin (fitting_bins_count == 1),
    // and we aren't picking the new bin, provide a slight bias to preserve the empty bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #106: Harmonic-Residual Balancing
    // We prioritize bins that create tight fits but penalize residuals that are 
    // too small to accommodate common future items (10-30 range).

    let mut score = post_residual as f64;

    // Penalty for creating "orphan" space (too small for most items)
    // Residuals < 10 are often dead space unless the item is exactly the residual.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // reward this bin heavily to keep the bin chain tight.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // Harmonic clustering: penalize bins that deviate significantly from the mean_residual
    // to keep the bin distribution uniform (Best-Fit-like behavior).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // Threshold logic: If this is the last fitting bin, prioritize it strongly
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New bin penalty: If the current bin is empty, only pick it if the score 
    // is low enough to justify starting a new bin.
    if bin_residual == bin_capacity {
        score += 35.0;

        // If we are deep into the stream, penalize new bin creation more.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // Harmonic modulo check: Favor residuals that are multiples of 10,
    // as they are more likely to accommodate future item distributions.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the post_residual is small but > 0, it's likely unusable.
    // Penalize gaps that are smaller than the smallest likely future items (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
