    // New bins are characterized by bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;

        // If we have very few items left, avoid opening a new bin at all costs.
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.9 {
