        }
    }

    // 4. Tight fit reward: Best-Fit logic.
    // Smaller post_residual is generally better, but we balance it against the 
    // risk of creating "dead" space.
    if post_residual == 0 {
        score -= 20.0; // Strongly prefer perfect fits
    }

    // 5. Global efficiency: If we have many fitting bins, be more selective.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin:
    // If bin is empty, assign a baseline cost that scales with how many bins are already open.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 2. Lookahead matching:
    // If the next item fits perfectly into the post_residual, drastically reduce the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward tight fits that leave little room for the next item
        score -= (100.0 - diff) * 0.3;
    }

    // 3. Fragmentation avoidance:
    // Penalize post_residuals that are small but unusable (1-9 range) 
    // unless they are exactly 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Density Balancing:
    // If the current post_residual is significantly lower than the mean_residual of other bins,
    // we are packing this bin tighter than average, which is good.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // 5. Urgency factor:
    // If this is the last fitting bin available, prioritize filling it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 6. Progression scaling:
    // As we reach the end of the stream, prioritize closing bins (lower residual = better).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
