        score += (progress * 50.0);
    }

    // If this bin is the last chance for the current item, prioritize it 
    // unless it results in a very poor fit (high post_residual).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // Balance against the mean residual of the system to prevent bin fragmentation.
    // If this bin's post_residual is significantly worse than the system mean, penalize.
    if (post_residual as f64) > mean_residual {
