    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res;

    // Penalty for leaving a 'dead zone' (e.g., 1-9 capacity left) which is hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if next item is large, avoid leaving small residuals
    if next_item_size > 0 {
        let potential_next_res = post_residual as i32 - next_item_size as i32;
        if potential_next_res < 0 {
            // If the current placement makes it impossible to fit the next item, 
            // penalize based on how much the next item would have preferred this space.
            score += (next_item_size as f64) * 0.5;
        }
    }

    // Dynamic Pressure: As the stream progresses, prioritize closing bins (lower open_bins_count)
    // We dampen the penalty for opening a new bin by coupling it with the mean_residual of existing bins.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // We only open a new bin if the average residual of current bins is already quite low (highly fragmented).
        score += mean_residual * (1.0 + progress) * 0.8;

        // If we have many fitting bins, opening a new one is usually bad unless they are all poor fits.
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 25.0;
        }
    } else {
        // Existing bin bonus: reward bins that are 'near' the mean residual to encourage consolidation.
        let dev_from_mean = (post_res - mean_residual).abs();
        score -= dev_from_mean * 0.2;
    }

    // Final scaling: favor placements that maintain a balanced distribution of residuals
    score += (open_bins_count as f64) * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
