    // 4. Pressure management: If fitting_bins_count is low, prioritize filling existing bins
    // to keep the number of active bins from exploding.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Reward tight fits (Best Fit principle)
    // Lower post_residual is generally better, but we already added penalties for "dead" zones.
    // We scale the post_residual to favor bins that reach high utilization.
    score += (post_residual as f64) * 0.5;

    // 6. Global progression: As we approach the end of the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
