        score -= (100.0 - (post_residual - next_item_size) as f64) * 0.1;
    }

    // 3. Global State Balancing: Avoid opening new bins early in the stream unless necessary.
    // If bin is empty (new bin candidate), penalize based on current open bin density.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: higher if we have many bins or near end of stream
        let open_penalty = (open_bins_count as f64 * 2.5) + (progress * 20.0);
