    score -= (1.0 - (post_residual as f64 / bin_capacity as f64)) * 5.0 * progress;

    // 5. Last chance bias: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
