    // We penalize post_residuals that are small but not zero (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if next_item_size fits in post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    }

    // Dynamic threshold: As the stream progresses, become more conservative about opening new bins
    if is_new_bin {
        // High penalty for opening new bins; the penalty decays as the stream nears the end
        // to ensure we don't end up with many half-empty bins at the very end
        score += 40.0 * (1.0 - progress).powf(0.5);

        // If we have many open bins, penalize opening another one
        score += (open_bins_count as f64) * 2.0;
    } else {
        // Reward bins that bring the mean residual closer to the next_item_size
        // This encourages "Best Fit" behavior
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // If this is the last chance to fit the item in an existing bin, reduce penalty
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for empty bins: only open a new bin if the fit in existing ones is extremely poor
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // Harmonic packing: penalize post_residuals that create "dead zones" (e.g., < 10, which is the minimum item size)
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: if the next item can fit in the current post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Efficiency bias: prefer bins that are closer to the mean residual to keep bin levels balanced
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // Pressure factor: as the stream progresses, become more aggressive in filling bins tightly
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // Constraint: if this is the only bin that can fit the item, prioritize it strongly to avoid new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Harmonic class logic: reward residuals that are multiples of common item sizes (e.g., 20, 25, 33)
    if post_residual % 20 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

