    // We penalize larger post_residuals to encourage filling bins as much as possible.
    score += (post_residual as f64).powf(1.2);

    // 2. Lookahead Match: If next_item_size fits in the post_residual, drastically reduce the score.
    // This rewards placements that leave exactly enough space for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
