    // 3. New Bin Management: 
    // If this is a new bin (bin_residual == bin_capacity), make it expensive unless necessary.
    // We only want to open a new bin if the mean_residual of existing bins is already small (compacting).
    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.5);
    } else {
        // 4. Distribution Balancing: 
        // Penalize bins that deviate significantly from the mean_residual to keep bin fill levels uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 5. Last Chance Heuristic:
    // If this is the only bin that can fit the item, prioritize it heavily to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progress Scaling:
    // As we approach the end of the stream, be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
