        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    // Non-linear coupling: penalize bins that deviate significantly from the mean residual.
    // This promotes "leveling" the load across bins.
    let dev = (post - mean_residual).abs();
    score += dev * 0.2 * (1.0 - progress);

    score
}

