pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for creating small, unusable gaps (1-9) which are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: Reward placing an item if it leaves room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0; // Strong reward for potential Best-Fit lookahead match.
        } else {
            score += 15.0; // Penalty for blocking a future fit.
        }
    }

    // Dynamic thresholding: As we approach the end of the stream, prioritize closing bins.
    if progress > 0.85 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // If this is the last chance for this item, reduce penalty for poor fit to avoid opening new bins prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Heuristic for new bin creation:
    // Only open a new bin if the current bin's residual is very high (bad fit) 
    // or if the current bins are all nearly full.
    if bin_residual == bin_capacity {
        // High cost to open a new bin unless the avg residual is already very small.
        score = 40.0 + (mean_residual * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space remaining after placement.
    // Minimizing this (Best Fit) is the primary objective.
    let mut score = post;

    // Penalty for creating "dead space" that is too small to be useful (less than 10).
    // As we approach the end of the stream (progress -> 1.0), we become more 
    // tolerant of small residuals because there are fewer opportunities to fill them.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 + progress * 2.0);
    }

    // Lookahead logic: If the next item can fit in the current post_residual,
    // we heavily reward this bin to encourage packing pairs.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // Strategic control for opening new bins:
    // If this is an empty bin (bin_residual == bin_capacity), we add a cost
    // that decreases as the stream progresses, allowing for more aggressive 
    // packing early on and more bin-opening freedom near the end.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early, lower penalty later.
        score += 35.0 * (1.0 - progress * 0.5);

        // If there are other bins that could fit the item, penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    } else {
        // For existing bins, favor bins that are closer to the mean residual
        // to keep the distribution of bin fullness balanced.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Final non-linear dampening: scale by the number of open bins to prevent 
    // fragmenting space across too many containers.
    score += (open_bins_count as f64).powf(1.2) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead zones" (small remainders that are unlikely to fit future items)
    // We target residuals that are multiples of common item sizes or near-zero.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Harmonic-based preference: favor bins where the remaining space is a multiple of the next item
    if next_item_size > 0 {
        let remainder = post_residual % next_item_size;
        // Reward placements that leave exactly enough room for the next item
        if remainder == 0 {
            score -= 25.0;
        } else if remainder < (next_item_size / 2) {
            score += 10.0;
        }
    }

    // Heuristic: If we are nearing the end of the stream, prioritize packing tighter
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 20.0);

    // If this bin is the only one that can fit the item, we are forced to use it.
    // However, if we are considering opening a NEW bin (residual == capacity), 
    // we penalize it unless the current open bins are very full.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is already quite high
        // (meaning they are already inefficiently packed)
        score += (mean_residual * 0.5);

        // If there are many fitting bins, it is almost always better to use one of them 
        // rather than opening a new one.
        score += (fitting_bins_count as f64 * 30.0);
    } else {
        // For existing bins, favor those that bring the residual closer to the mean_residual
        // to keep bin utilization balanced.
        let diff = (post_residual as f64 - mean_residual).abs();
        score += diff * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1-9), it is likely "unusable" 
    // because the minimum item size is 10. We penalize this heavily to favor tighter fits.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Integration: If the next item exists, try to preserve space for it.
    // If the post_residual is less than the next item, we penalize the bin because 
    // it forces the next item into a new bin or a different existing bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 20.0;
        } else {
            // Reward bins that can accommodate the next item perfectly
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
