    // 3. Open Bins Pressure: Penalize opening new bins when current bins are available.
    // If this is a new bin (bin_residual == bin_capacity), add a heavy penalty 
    // unless the fitting_bins_count is 0.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 100.0 + (open_bins_count as f64 * 5.0);
        } else {
            score -= 10.0; // Encourage opening a new bin if no other options exist
        }
    }

    // 4. Mean Residual Balancing: Prefer bins closer to the mean to maintain 
    // a consistent fill profile across the bin set.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    // 5. Progression Scaling: As we approach the end of the stream, prioritize 
    // consolidation (lower residual) over long-term flexibility.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We want to minimize post_residual, so it stays as the base score.

    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward this bin.
    // We reward placements where the post_residual can accommodate the next item perfectly.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= 50.0 / (1.0 + diff);
    }

    // 3. Fragmentation Control: Penalize bins that leave behind "dead space" 
    // that is smaller than the smallest likely item (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
