        }
        // If we are late in the stream, be more conservative about opening new bins
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 5. Mean Residual Balancing: 
    // Avoid bins that deviate significantly from the average state of our bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 6. Last Chance Logic:
    // If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
