    // New-bin logic: If this is an empty bin (new bin candidate)
    if bin_residual == bin_capacity {
        // If we have many open bins, penalize opening a new one heavily.
        // If we have few open bins, opening a new one is cheaper.
        score += (open_bins_count as f64 * 2.5) + (progress * 10.0);
    } else {
        // If this is an existing bin, favor it if it is the last chance for the item
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Penalize bins that deviate too far from the mean residual to keep bin usage balanced
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Prioritize Best-Fit: penalize larger post_residuals
    // The objective is to keep post_residual as small as possible (tight packing).

    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward it.
    // We want post_residual to be >= next_item_size if possible to minimize new bin creation.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward placements that leave enough room for the next item
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs());
        } else {
            // Penalize placements that make the next item impossible to fit in this bin
            score += 50.0;
        }
    }

    // 3. New Bin Penalty: Heavily penalize opening a new bin unless necessary.
    // If this is a new bin, bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if we absolutely have to or if current bins are very full
            score += 200.0;
        } else {
            score -= 50.0;
        }
    }

    // 4. Global Density Awareness: 
    // If our current bin is much emptier than the average, we prefer filling it.
    // If it's much fuller, we prefer saving it for smaller items.
    let residual_delta = bin_residual as f64 - mean_residual;
    score += residual_delta * 0.5;

    // 5. Urgency: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 20.0 * (1.0 / (fitting_bins_count as f64 + 1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Current progress factor (0.0 to 1.0)
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-residual (Best Fit principle: minimize waste)
    let mut score = post_residual as f64;

    // Penalty for creating small, unusable gaps (1..9 is often "dead space")
    if post_residual > 0 && post_residual < 10 {
        score += 35.0 * (1.0 + progress);
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it later
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that keep capacity for the next item
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 10.0; // Penalize bins that block the next item
        }
    }

    // Global state awareness: If we have many open bins, be more aggressive with packing (Best Fit)
    // If we have few open bins, be more cautious about opening new ones
    if bin_residual == bin_capacity {
        // Scoring the "New Bin" option
        if open_bins_count > 0 {
            // Penalize opening a new bin heavily unless we are at the very start 
            // or the existing bins are all very tight (high utilization)
            score += 40.0 + (mean_residual * 0.5);
        }
    } else {
        // Favor bins that align with the global mean residual to keep distribution uniform
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;

        // If this is the last chance to fit the item in an existing bin, favor it
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Time-horizon decay: As we approach the end of the stream, prioritize closing bins
    score -= (progress * 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating a bin that is too small for the lookahead item.
    // If next_item_size is 0 (end of stream), this penalty is negligible.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 1.5;
    }

    // Penalize opening a new bin (where bin_residual == bin_capacity) 
    // unless the stream is early or the current average residual is very poor.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + (mean_residual * 0.5);
    }

    // Reward bins that have a post_residual close to the mean_residual,
    // discouraging fragmentation by keeping bin states clustered.
    let residual_deviation = (post - mean_residual).abs();
    score += residual_deviation * 0.8;

    // If this is the only bin that can fit the item, prioritize it strongly
    // to avoid unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Non-linear coupling: as we reach the end of the stream, 
    // tighten the tolerance for post_residual to minimize wasted capacity.
    score += (post * post) / (bin_capacity as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but unusable for common item sizes
    // (e.g., leaving 5-9 space is often worse than 0-4).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into this bin's new residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let remainder = post_residual - next_item_size;
        // Reward filling space to near-zero or leaving space for a large item
        if remainder == 0 {
            score -= 30.0;
        } else if remainder >= 20 {
            score -= 10.0;
        }
    }

    // 3. Efficiency Threshold: If this is the only bin that fits the item, avoid opening a new one.
    // We treat the "New Bin" candidate (bin_residual == bin_capacity) with a base cost.
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is high; only do it if the existing options are very poor.
        score = 55.0 + (open_bins_count as f64 * 0.5);
    } else {
        // Penalty for creating "fragmented" bins that deviate from the mean residual.
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.2;
    }

    // 4. Harmonic Modulo Logic: Prefer bins that leave space divisible by common sizes (20, 25, 50).
    if post_residual % 25 == 0 {
        score -= 15.0;
    } else if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 5. Progression Scaling: As we reach the end of the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit common items
    // (1-9 is effectively unusable for the given range 10-80).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Penalize opening new bins unless necessary
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 40.0 + (open_bins_count as f64 * 0.5);
    }

    // 3. Lookahead: If next_item_size exists, favor bins that leave enough room for it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize cutting off the next item
            score += 25.0;
        } else {
            // Reward preserving space for the next item
            score -= 10.0;
        }
    }

    // 4. Pressure: If this is the only bin that fits, prioritize it heavily to avoid fragmentation
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // 5. Global Efficiency: If many bins are open, push for higher density
    // Penalize high residuals compared to the mean
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // 6. Progression: As the stream nears the end, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Favor bins that leave smaller post_residuals
    // (Already captured by base score, but we refine it below).

    // 2. Penalize opening a new bin prematurely
    if bin_residual == bin_capacity {
        // Only open a new bin if we have no options or the current options are very poor.
        // We add a penalty proportional to the number of bins already open to discourage fragmentation.
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 3. Lookahead Matching: If post_residual is close to next_item_size, it's a high-value placement.
    // We reward placements that leave exactly enough space for the next item.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        score -= 20.0 / (1.0 + diff);
    }

    // 4. Mean Residual Balancing: Avoid leaving bins significantly emptier than the current average.
    // This keeps bin utilization consistent.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // 5. Criticality: If this is the only bin that can fit the item, prioritize it heavily
    // to avoid the penalty of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progression scaling: As we approach the end of the stream, prioritize tight fits
    // to reduce the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize score.
    // 1. Base cost is the remaining space (Best Fit principle).
    let mut score = post_residual as f64;

    // 2. Penalize creating "dead zones" (residuals < 10 are hard to fill given the distribution).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead logic: If the next item can fit in the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 4. Global state: If we are near the end of the stream, prioritize packing tighter.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    // 5. New Bin logic: 
    // If this is a new bin (residual == capacity), penalize it based on how many bins are already open.
    // We only want to open a new bin if the existing fits are objectively terrible (high post_residual).
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.0);
    }

    // 6. If this is the only fitting bin, give it a slight preference to avoid opening new bins unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // 7. Balance against the mean residual of the system to prevent bin sprawl.
    if (post_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle).
    // Penalize large post_residuals quadratically to avoid fragmentation.
    let mut score = post_res * post_res;

    // Lookahead logic: if next_item_size exists, favor bins that can accommodate it.
    // If post_residual is too small to fit the next item, penalize the bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size as f64 - post_res) * 50.0;
        }
    }

    // Dynamic adaptation: As we approach the end of the stream, 
    // prioritize filling existing bins more aggressively to avoid opening new ones.
    let new_bin_penalty = (1.0 - progress) * 2500.0 + (open_bins_count as f64 * 10.0);

    if bin_residual == bin_capacity {
        // This is the "Open New Bin" candidate.
        score = new_bin_penalty;
    } else {
        // If this bin is the only one that can fit the current item, 
        // give it a significant boost to prevent forced new bin creation.
        if fitting_bins_count == 1 {
            score -= 1000.0;
        }

        // Penalize bins that deviate significantly from the mean residual 
        // to encourage uniform fill levels across the set of open bins.
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "fragmented" space that is too small for common items (below 10)
    // but not zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic Class Logic: 
    // Prefer bin configurations that leave room for the lookahead item.
    // If next_item_size fits in the post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // If this is the only bin that can fit the item, prioritize it to avoid 
    // unnecessary new bins, unless it leaves a very poor residual.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Discourage opening a new bin if we have many bins already, 
    // unless the residual is very high (meaning we are wasting space).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 20.0;
        }
        // If we are near the end of the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0;
    }

    // Harmonic penalty: Penalize residuals that are close to half the capacity 
    // (creating "unfillable" gaps for large items).
    let mid = bin_capacity / 2;
    if post_residual > (mid - 5) && post_residual < (mid + 5) {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: Heavily penalize small gaps that are unlikely to fit future items.
    // If post_residual is in the range (0, 10), it is highly likely to become unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead optimization: If next_item_size is known, penalize placements 
    // that prevent the next item from fitting in this bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // 3. Open bins pressure: Balance the desire to consolidate items into fewer bins.
    // If fitting_bins_count is 1, we are at a critical juncture; avoid opening a new bin
    // unless the current fit is extremely poor (high post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the current mean_residual across existing bins is already very low,
        // or if we have very few open bins (encouraging consolidation).
        score += (open_bins_count as f64) * 5.0;
        if mean_residual > 20.0 {
            score -= 25.0;
        }
    } else {
        // Reward filling bins to reduce open_bins_count.
        score -= (open_bins_count as f64) * 0.5;
    }

    // 4. Progress-aware scaling: As the stream nears completion, become more aggressive 
    // about packing tightly to avoid stranding items in new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Prioritize Best-Fit (minimize post_residual)
    // 2. Penalize opening a new bin unless the remaining space is very inefficient
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: only do it if the average residual of existing bins is already tight
        score += 25.0 + (mean_residual * 0.5);
    } else {
        // 3. Lookahead Logic: If next_item_size fits in the post_residual, reward this placement
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
            // Further reward if it fills the bin nearly perfectly
            if post_residual - next_item_size < 5 {
                score -= 20.0;
            }
        }

        // 4. Penalty for creating "orphan" space (too small for most items)
        if post_residual < 10 && post_residual > 0 {
            score += 12.0;
        }

        // 5. If this is the only bin that fits the current item, prioritize it strongly
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 6. Dynamic Scaling: As the stream progresses, become more aggressive about filling existing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

