}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight (Best-Fit principle).
    // We penalize larger post_residuals heavily.
    score += (post_residual as f64).powf(1.2);

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // reward this bin to keep the next item packed tightly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Last Chance Logic: If this is the only bin that can fit the current item,
    // strongly favor it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 4. New Bin Thresholding: Penalize opening a new bin unless the current 
    // options are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low, 
        // suggesting we are wasting space in existing bins, or at the very end 
        // of a stream to avoid fragmentation.
        score += 40.0 + (mean_residual * 0.5) + (progress * 20.0);
    }

    // 5. Global State Balancing: If we have many open bins, penalize spreading 
    // items thin. If few, be more permissive to keep residuals high.
    score += (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the creation of a new bin (bin_residual == bin_capacity) 
    // proportionally to the progress to favor packing later in the stream.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (25.0 + (progress * 50.0));

    // Reward bins that leave a post_residual that matches the next_item_size,
    // creating a "perfect fit" lookahead.
    let lookahead_affinity = if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        // Lower score (better) if the post_residual is close to the next item
        -15.0 * (1.0 / (1.0 + diff))
    } else {
        0.0
    };

    // Penalize small "fragment" residuals that are unlikely to fit future items (e.g., < 15)
    // especially as the stream progresses.
    let fragment_penalty = if post < 15.0 && post > 0.0 {
        (15.0 - post) * (1.0 + progress)
    } else {
        0.0
    };

    // Encourage filling bins that are already partially full (high mean_residual implies many empty bins)
    // We normalize the influence of the current bin's state against the global state.
    let capacity_utilization_incentive = (bin_capacity as f64 - post) * 0.1;

    let mut score = post 
        + new_bin_penalty 
        + lookahead_affinity 
        + fragment_penalty 
        - capacity_utilization_incentive;

    // Discourage opening a new bin if other bins are still available (fitting_bins_count > 0)
    if is_new_bin > 0.0 && fitting_bins_count > 0 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (wasted space)
    // 2. Harmonic penalty for small residuals (fragmentation)
    if post_residual > 0 {
        score += 100.0 / (post_residual as f64 + 1.0);
    }

    // 3. Lookahead optimization: If next_item_size is known, reward bins that can accommodate it
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0; // Strong preference for bins that keep the next item packable
    }

    // 4. Thresholding: If this is the last fitting bin, penalize the creation of a new bin
    // unless the current fit is extremely poor (post_residual > 40)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual > 40 {
            score += 200.0;
        } else {
            score -= 150.0; // Strongly prefer existing bin over new one
        }
    }

    // 5. Global state normalization: discourage opening new bins as the stream progresses
    // unless the residual is very tight
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
        score += mean_residual * 0.5;
    }

    // 6. Harmonic classes: avoid creating residuals that are "useless" (e.g., < 10)
    // if a larger residual would allow more flexibility for future items.
    if post_residual > 0 && post_residual < 10 {
