pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_res;

    // Penalty for "fragmentation": If post_residual is small but > 0, it's often unusable.
    // We penalize values < 10 specifically as "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: If the next item is large, we want to preserve bins with high residuals.
    // If we are late in the stream, we become more aggressive in packing tightly.
    if next_item_size > 0 {
        let next_item = next_item_size as f64;
        // If the current bin cannot fit the next item but others can, penalize this bin.
        if (post_residual as f64) < next_item {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Encourage using existing bins when fitting_bins_count is low to avoid opening new ones.
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is already tight (< 15)
        // or if we have no other choice.
        if fitting_bins_count > 0 {
            score += 40.0 + (mean_residual * 0.5);
        } else {
            score -= 5.0; // Force opening a new bin if no other options exist.
        }
    }

    // Nonlinear coupling: As we approach the end of the stream, prioritize tight packing (lower post_residual).
    // We apply a cubic weight to the post_residual to heavily punish large gaps at the end.
    score += (post_res.powf(2.0) / bin_capacity as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
