    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit future items.
    // If post_residual is between 1 and 9, it's highly likely to become unusable (since min size is 10).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // 2. Lookahead Synergy: If the next item can fit in this post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening a new bin if we have existing capacity.
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 4. Fitting Density: If this is the only bin that can fit the item, reward it to avoid 
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Residual Balancing: Penalize bins that deviate significantly from the mean residual
    // to keep bin utilization uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 6. Progressive Tightening: As we approach the end of the stream, prioritize 
    // tighter fits (lower post_residual) to maximize packing efficiency.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals.
    // We want the post_residual to be as close to 0 as possible.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Synergy: If the next item fits perfectly into the current post_residual,
    // we drastically lower the score to prioritize this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 / (1.0 + diff)) * 50.0;
        } else {
            // Penalty if the next item cannot fit, proportional to how much we wasted.
            score += 20.0;
        }
    }

    // 3. Pressure Management: If we are running out of space (low mean_residual),
    // favor bins that keep the mean_residual high for future items.
    if mean_residual < 20.0 {
        score -= (bin_residual as f64) * 0.5;
    }

    // 4. Avoid opening new bins prematurely:
    // If this is a new bin (residual == capacity), add a heavy penalty unless it's the only choice.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 50.0;
        }
    }

    // 5. Last-chance logic: If this is the only bin that fits, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 6. Progression normalization: As we approach the end of the stream, 
    // prioritize tighter packing to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Current progress normalized [0.0, 1.0]
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-placement residual. 
    // Lower residual (tighter fit) is generally better (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space":
    // If the post_residual is too small to fit any likely future items (e.g., < 10), 
    // it creates unusable fragmentation. We penalize this heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Awareness:
    // If we have a next_item, prefer bins that can accommodate it.
    // If the current bin will be too small for the next item, we penalize it 
    // to encourage keeping room for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward bins that maintain perfect compatibility for the next item
            score -= 5.0;
        }
    }

    // 3. Dynamic Threshold for New Bin Opening:
    // If this is a new bin (bin_residual == bin_capacity), score it based on global state.
    // We only open a new bin if the current mean_residual is already quite tight,
    // or if the progress is near the end and we want to consolidate.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = 45.0; 

        // If we have many open bins with large residuals, reuse them instead.
        if mean_residual > 30.0 {
            score += 40.0;
        }

        // Late-stage consolidation: discourage new bins when nearing completion.
        score += progress * 20.0;
    }

    // 4. Scarcity adjustment:
    // If this is the ONLY bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global State Balancing:
    // Penalize bins that deviate too far from the current mean_residual 
    // to keep the bin distribution uniform.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize tightest fit (Best Fit)
    let mut score = post;

    // Penalty for creating "slivers" (very small residuals that are hard to fill)
    // We penalize residuals between 1 and 9 significantly.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: If a future item is large, favor keeping space open.
    // If the next item is large (> 60), we penalize placing this item if it creates a tight fit
    // that would otherwise accommodate a larger item.
    if next_item_size > 60 && post < 40.0 {
        score += 15.0 * (1.0 - progress);
    }

    // Dynamic pressure: As the stream progresses, prioritize closing bins to reduce open_bins_count.
    // High open_bins_count increases the penalty for opening a new bin (post == 100).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0 * (1.0 + progress);
    }

    // Global balance: If the current bin is significantly tighter than the mean,
    // reward it to keep the average utilization high.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0 * (1.0 - progress);
    }

    // Critical constraint: If this is the only bin that fits, prioritize it strongly
    // unless the fit is extremely poor (sliver-inducing).
    if fitting_bins_count == 1 && post > 5.0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
