    }

    // Lookahead logic: if next_item_size is large, favor bins with enough residual to fit it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual < 20 {
            // Avoid creating "sliver" space that is too small for common items
            score += 10.0;
        }
    }

    // Harmonic/Modulo heuristic: penalize remainders that are unlikely to fit standard item ranges
    // Items are 1-100; residuals < 10 are often "dead" space
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Global state awareness: if we have many bins open, be more aggressive with packing
    if open_bins_count > (total_items / 10) {
