    // Residuals between 1 and 9 are extremely difficult to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: reward bins that can accommodate the next item.
    // If the next item fits perfectly or well into the remaining space, prioritize this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportionally to how tightly the next item fits (Best Fit for next item)
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.5;
        } else {
            // Penalize if this placement prevents the next item from fitting here
            score += 20.0;
        }
    }

    // 3. Balance bin usage: avoid opening new bins if existing ones are suitable.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Only open a new bin if the current open bins are very full (low mean residual)
            // or if no existing bins can fit the item (fitting_bins_count == 0).
            if fitting_bins_count > 0 {
                score += 80.0; // High penalty for opening a new bin unnecessarily
            } else {
                score -= 10.0; // Necessary to open
            }
        }
    }

    // 4. Global density management:
    // If we are late in the stream, prioritize clearing existing bins (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * progress * 0.5;

    // 5. Tie-breaking: Use mean_residual to keep bins at similar fill levels.
    // Penalize bins that deviate significantly from the mean to encourage "level" filling.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
