    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if others can fit the item
            score += 60.0 + (open_bins_count as f64 * 2.0);
        }
        // Time horizon adjustment: be more aggressive about new bins late in the stream
