        // This is a non-linear coupling: we favor bins that can accommodate the next item.
        if next_item_size > 0 {
            let gap_to_next = (post - next_item_size as f64).abs();
            score -= 15.0 * (1.0 - gap_to_next / bin_capacity as f64).powi(2);
        }

        // Penalty for bins that become "fragmented" (too small to fit common items)
        // We define fragmentation as having a small post_residual that is unlikely to fit anything.
        if post > 0.0 && post < 15.0 {
            score += 20.0 * (1.0 - post / 15.0);
        }
    }

    // Interaction with global bin state:
    // If many bins are open, we penalize creating more, encouraging consolidation.
    score += (open_bins_count as f64).powf(1.2) * 2.0;

    // Final correction: bias against extremely tight fits if it leaves a "sliver"
    // that is statistically unlikely to be filled.
    if post > 0.0 && post < 5.0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #326: Harmonic-Residual Coupling
    // Objectives:
    // 1. Minimize post_residual (Best Fit).
    // 2. Penalize "Dead Space" (post_residual < 10) unless it's a perfect fit.
    // 3. Use lookahead to avoid stranding small items in bins that could fit larger ones.
    // 4. Harmonic scaling: favor bins that leave space for common harmonic fractions (e.g., 1/2, 1/3, 1/4 of capacity).

    let mut score = post_residual as f64;

    // Penalty for creating "sliver" spaces that are too small for most items (1-9)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
