    // Lookahead logic: if next_item_size is large, avoid bins that would leave it un-fittable
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // Harmonic bias: If we are creating space, target residues that are multiples of 20 (1/5th capacity)
    // to keep bins aligned for future medium-sized items.
    let harmonic_penalty = (post_residual % 20) as f64;
    score += harmonic_penalty * 0.5;

    // Favor filling bins that are already "half-empty" (mean_residual logic)
    // If this bin is significantly emptier than the average, prioritize filling it.
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    }

    // If this is the only bin that fits, prioritize it strongly to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Discourage opening a new bin unless the fit is perfect or we are forced to
    if bin_residual == bin_capacity {
        score += 25.0;
        // As the stream progresses, make it slightly harder to open new bins
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
