        }
    }

    // 5. Global Efficiency: If the current bin's residual is significantly better than the mean,
    // reward it to encourage filling existing bins rather than spreading items thin.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
