    // 3. Utilize lookahead (next_item_size) to avoid creating "dead zones" (residuals that can't fit upcoming items).

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: Favor smaller post_residual (Best-Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a new bin
    if is_new_bin {
        // Only open a new bin if we have many bins open already or if we are early in the stream
        // and current open bins are already very full.
        score += 45.0 + (mean_residual * 0.5) + (progress * 20.0);
    } else {
        // If this is the last chance for the current item, prioritize it slightly
        if fitting_bins_count == 1 {
            score -= 10.0;
