    // prioritize it to avoid splitting the stream into more bins than necessary.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Mean residual balancing: Prefer bins that stay close to the mean to maintain 
    // uniformity in bin packing levels.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" bins (residual too small to fit common items)
    // Small residuals (1..10) are often dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2. Aggressive 2-step lookahead: 
    // Reward placements that leave exactly enough space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
