    // 4. Handle the "New Bin" candidate case
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are extremely tight
        // or if we are nearing the end of the stream and need to clear space.
        let progress = step_index as f64 / total_items as f64;
        score += 50.0 + (progress * 30.0);

        // If we have many bins open, penalize opening another one
        score += open_bins_count as f64 * 2.0;
    } else {
        // If it's a fitting bin, prioritize based on how well it packs
        // Reward bins that have few alternatives (fitting_bins_count == 1)
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
