    // 5. Mean Residual Alignment: Favor bins that keep the bin closer to the average utilization
    // to maintain a balanced packing profile.
    let current_utilization = bin_capacity - post_residual;
    let deviation = (current_utilization as f64 - (bin_capacity as f64 - mean_residual)).abs();
    score += deviation * 0.1;

