    score += (post_residual as f64) * 0.5;

    // 2. Lookahead Synergy: If the next item fits into the post_residual, 
    // heavily reward this bin to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;

        // Additional incentive if the pair leaves almost no space (near-perfect fit).
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 3. New Bin Thresholding: 
    // If this is a new bin (residual == capacity), penalize it unless the 
    // current fitting_bins_count is low or the residual in existing bins is poor.
    if bin_residual == bin_capacity {
        score += 35.0; // Base cost to open a new bin

        // If we have many options to fit the item, discourage opening a new one.
        score += (fitting_bins_count as f64) * 5.0;

        // If the mean residual of existing bins is already very low, 
        // it's better to use an existing bin than start a new one.
        score += (100.0 - mean_residual) * 0.2;
    } else {
        // 4. Existing Bin Optimization:
        // Penalize bins that deviate significantly from the mean residual
        // to keep usage density uniform across bins.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 5. Progression weighting: 
    // As we approach the end of the stream, be more aggressive with packing
    // to avoid leaving too many bins with small residuals.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best Fit Decreasing logic: reward smaller post_residual
    // 2. Penalize opening new bins unless the current fit is terrible (e.g., > 20% waste)
    if is_new_bin {
        if fitting_bins_count == 0 {
            score = 10.0; // Forced: must open new bin
        } else {
            // Penalize new bin opening proportional to how much space is wasted in current bins
            score = 80.0 + (mean_residual * 0.5) + (progress * 20.0);
        }
    } else {
        // 3. Lookahead: If next item fits in this post_residual, reward the placement
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        }

        // 4. Fragment Prevention: Penalize creating "dead zones" (small residuals)
        // A residual < 10 is usually unusable for items > 10
        if post_residual < 10 && post_residual > 0 {
            score += 45.0;
        }

        // 5. Global state: If many bins are open, prioritize tightening existing bins
        if open_bins_count > (total_items / 20) {
            score -= (bin_capacity - bin_residual) as f64 * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

