    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As the stream progresses, we become more conservative about opening new bins.
    // We scale the penalty by the current efficiency (mean_residual).
    if is_new_bin {
        score += 15.0 + (progress * 25.0) + (mean_residual * 0.5);
    } else {
        // Reward bins that leave space for the next item (Lookahead optimization)
        // If the current bin can fit the next item, we favor it.
        if next_item_size > 0 && post_residual >= next_item_size {
