        // Penalty for "fragmentation" (creating very small, unusable residuals)
        // We penalize residuals that are too small to fit the smallest expected items (10)
        // but not zero (which is perfect).
        if post_residual > 0 && post_residual < 10 {
            score += (10.0 - post_residual as f64) * 2.5;
        }

        // If this is the last chance to fit an item (fitting_bins_count == 1),
        // we heavily prioritize this bin to prevent unnecessary new bin creation.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Interaction term: coupling progress with the number of open bins.
    // As the stream nears the end, we want to consolidate into fewer bins.
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
