        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Penalize opening new bins when current bins are available, unless the fit is perfect
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 40.0;
        }
    }

    // 3. Lookahead logic: if next_item_size is large, favor bins that leave enough room for it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a bin that cannot accommodate the next item
            score += 15.0;
        } else {
            // Reward bins that can accommodate the next item (synergy)
            score -= 5.0;
        }
    }

    // 4. Pressure: If many bins are open, aggressively try to fill those with low residuals
    // to reduce total count, penalizing bins that significantly deviate from the mean_residual
    if open_bins_count > 5 {
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 5. If this is the only bin that fits the current item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals.
    // The base score is already post_residual, which favors tight packing.

    // 2. Lookahead Synergy: If the post_residual can perfectly or nearly accommodate the next item, 
    // prioritize this bin significantly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that create a "perfect" fit for the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 / (1.0 + slack);
        } else {
            // Penalize if this bin becomes unusable for the next item while others might remain open.
            score += 15.0;
        }
    }

    // 3. Fragmentation Control: Avoid creating "dead" space (e.g., < 10 units) if possible.
    // If post_residual is small but > 0, it is likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Density Balancing: Compare this bin's post_residual to the global mean_residual.
    // Bins that bring the mean closer to a target density are preferred.
    let target_residual = 15.0; 
    score += (post_residual as f64 - target_residual).abs() * 0.5;

    // 5. New Bin Threshold: If this is a new bin, apply a heavy penalty unless the 
    // fitting_bins_count is very low or the item is large.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one works.
            score += 60.0;
        } else {
            // Opening a new bin is necessary.
            score -= 20.0;
        }
    }

    // 6. Progressive Scaling: As the stream nears the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best-Fit principle)
    // Already initialized as post_residual.

    // 2. Dead-space avoidance: Penalize remaining space that is too small for common items.
    // If post_residual is < 10, it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 3. Lookahead integration: If the next item fits into the post_residual, 
    // favor this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
