    // packing tightly rather than opening new bins.
    if progress > 0.8 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. New Bin Logic: If we are considering a new bin (bin_residual == bin_capacity),
    // penalize it heavily unless there are no good fits available.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if the mean residual of existing bins is very high
            // (i.e., we are already struggling with fragmentation).
            score += 60.0 + (mean_residual * 0.5);
        } else {
            // No other choice
            score = 10.0; 
        }
    }

    // 6. Fragmentation balance: Penalize bins that deviate significantly from the mean residual
    // to keep bin levels balanced (First-Fit Decreasing behavior).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
