    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Lookahead: If next_item_size is large, favor bins that can accommodate it later
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that maintain capacity for the next item
            score -= 25.0;
        } else {
            // Penalize bins that would be "trapped" by the current item
            score += 15.0;
        }
    }

    // 3. Density Balancing: Avoid over-filling bins too early if many items remain
    let progress = step_index as f64 / total_items as f64;
    if progress < 0.7 && post_residual < 15 {
        score += 10.0 * (1.0 - progress);
    }

    // 4. Fitting Pressure: If this is the only bin that can fit the item, prioritize it heavily
    if fitting_bins_count == 1 {
        score -= 100.0;
    }

    // 5. New Bin Thresholding:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only open if the average residual of existing bins is already very tight (< 15).
    if bin_residual == bin_capacity {
        if mean_residual > 15.0 {
            // New bins are expensive; penalize them unless existing ones are nearly full
            score += 40.0;
        } else {
            // Existing bins are tight, opening a new one is neutral
            score += 5.0;
        }
    }

    // 6. Harmonic Class Penalty: Favor packing into bins that result in "round" residuals
    // (multiples of 20) as they are more flexible for future arrivals.
    let remainder = post_residual % 20;
    score += remainder as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit common items (10-20 range)
    // If post_residual is in the "dead zone" (1..10), it is highly undesirable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Open Bins Pressure: Penalize opening new bins unless necessary
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is already quite low (bins are full)
        // or if we have very few bins open.
        score += (open_bins_count as f64 * 2.5) - (mean_residual * 0.5);
    } else {
        // If it's an existing bin, favor keeping the bin count low.
        score -= (open_bins_count as f64 * 0.2);
    }

    // 3. Lookahead coupling: If next_item_size is large, favor bins that can accommodate it.
    // If this bin's post_residual is too small for the next item, penalize it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. Fitting Density: If this is the last bin that can fit the item, prioritize it 
    // to avoid leaving "fragmented" bins that can't fit future items.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression adjustment: As we approach the end of the stream, 
    // be more aggressive about packing tightly.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
