    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Coupling with mean_residual: Encourage packing items into bins that are 
    // already "tighter" than the current average to maintain bin density.
    if post_residual < mean_residual as u32 {
        score -= (mean_residual - post) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a 'sliver' (small unusable space) which is hard to fill.
    // We prioritize bins that result in a post_residual that is either 0 (perfect fit)
    // or large enough to accommodate common item sizes (>= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: If a future item exists, favor bins that leave enough space for it.
    // If the current post_residual is smaller than the next item, we penalize it 
    // unless the current post_residual is exactly 0.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Harmonic class logic: Reward fits that align with common divisors of 100.
    // If the post_residual is a multiple of 20, it's highly flexible for future items.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // Avoid opening new bins unless necessary (fitting_bins_count == 0).
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless there are no other options.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 20.0; // Force-open if no other fit exists
        }
    }

    // Balance the load: Penalize bins that deviate too far from the mean_residual
    // to keep the bin distribution uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // Progression weight: In the final stages, prioritize filling existing bins
    // to minimize the total bin count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let post = post_residual as f64;
