    if is_new_bin {
        if fitting_bins_count > 0 {
            // Apply a heavy penalty to opening a new bin if we have room elsewhere.
            score += 60.0 + (mean_residual * 0.5);
        } else {
            // If no other option, normalize the cost of a new bin.
            score = 40.0;
        }
    }

    // Reward bins that keep the mean residual balanced.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

