    // Penalty for opening a new bin: if this is a new bin, apply a barrier
    // that scales with the progress of the stream.
    if bin_residual == bin_capacity {
        // As the stream progresses, we become more desperate/aggressive to close bins.
        // Penalty for opening a new bin decreases as we reach the end of the stream.
        score += 450.0 * (1.0 - progress).powf(0.8);
    } else {
        // If this bin is already open, favor it if it's "close to full" 
        // to consolidate space, but penalize if it leaves a "sliver" (bad residual).
        // A residual between 1 and 10 is often a "sliver" that kills packing efficiency.
        if post_residual < 10 && post_residual > 0 {
            score += 150.0 * (1.0 - progress);
        }

        // Lookahead synergy: if next_item_size is large, prioritize keeping 
        // this bin open if it can accommodate the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 120.0 * (1.0 - progress.powf(2.0));
        }
    }

    // Penalize bins that are significantly emptier than the current mean, 
    // to encourage filling existing bins rather than spreading items thin.
    let residual_deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * residual_deviation;

    // Favor bins that are currently the only ones able to take the item
    // to prevent leaving isolated items in bins that become hard to fill.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
