    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high.
        score += 45.0;
        // If we have many open bins that can fit this item, don't open a new one.
        score += (fitting_bins_count as f64) * 20.0;
    }

    // 4. Mean residual balancing: Penalize bins that deviate significantly from the average 
    // fullness of other bins to maintain uniform packing density.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.8;

    // 5. Progression awareness: As we approach the end of the stream, prioritize 
    // closing existing bins (lower penalty for small residuals).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
