    // Global state awareness: favor bins that align with the current mean residual
    // This helps maintain a uniform distribution of fill-levels across bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * deviation;

    // Final adjustment: prioritize bins that are "almost full" to maximize density
    // (100 - post_residual) is the filled amount; we want to maximize this (so subtract it)
    score -= 0.2 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
