pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Harmonic classes logic.
    // We prioritize bins that result in high-utility residuals (multiples of common item sizes).
    // We penalize opening new bins unless the residual in existing bins is highly inefficient.

    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Penalize new bins based on the current open bin count to prevent fragmentation.
    if is_new_bin {
