    // or fit common item sizes (like 20, 25, 33) to allow future items to pack tightly.
    let harmonic_penalty = match post_residual {
        0 => -20.0, // Perfect fit: highly rewarded
        r if r % 25 == 0 => -12.0,
        r if r % 20 == 0 => -10.0,
        r if r < 10 => 15.0, // Create "dead zones" that are too small for any item
        _ => 0.0,
    };
    score += harmonic_penalty;

    // 3. Lookahead coupling: If a large next item is coming, prioritize bins that 
    // have enough post_residual to accommodate it, or avoid stranding it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
