            score += 8.0;
        } else {
            // Reward if this bin can actually host the next item
            score -= 5.0;
        }
    }

    // 4. Mean Residual Balancing: If the current bin's post_residual is significantly 
    // lower than the global mean, it's a "tight" bin. We prioritize keeping tight bins.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Fitting Constraint: If this is the only bin that fits, prioritize it strongly
    // to avoid the penalty of opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
