    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // significantly reward this placement to keep bin density high.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when current ones can fit the item,
    // unless the current fit is extremely poor (Best Fit Decreasing logic).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only favor a new bin if we have too many fragmented bins already, 
        // or if the current bins are too full to accommodate average future needs.
        score += (open_bins_count as f64 * 2.0);
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    } else {
        // Favor packing into existing bins that become tighter (lower post_residual)
        // while penalizing bins that become "half-empty" (unusable for large items).
        if post_residual > 40 && post_residual < 60 {
            score += 15.0;
        }
    }

    // 4. Progress Scaling: As the stream nears completion, become more aggressive 
    // about closing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large residuals (prefer tight fits).
    // The base score is already post_residual, which inherently favors Best Fit.

    // 2. Lookahead Penalty: If the post_residual is too small to fit the next item,
    // and the next item is large, we penalize this bin to save it for a better match.
    if next_item_size > 0 {
        if post_residual < next_item_size {
