    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. New Bin Thresholding: Penalize opening a new bin unless the current 
    // residuals are extremely poor (above the mean).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 25.0 {
            score += 10.0; 
        } else {
            score += 45.0; // Strong penalty to force reuse of existing bins
        }
    }

    // 5. Global Density Balancing: As the stream progresses, tighten the requirements.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

