    };

    // Calculate a "tightness" penalty: 
    // If post_residual is small (e.g., < 10), it's likely "dead space" that cannot fit future items.
    // We prioritize bins where the post_residual is larger (Best-Fit variant) but 
    // penalized by the likelihood of the next item fitting.
    let dead_space_penalty = if post < 10.0 && post > 0.0 {
        20.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Lookahead: If next_item_size is large, avoid bins that result in small residuals (fragmentation)
    let lookahead_penalty = if next_item_size > 0 {
