    };

    // Favor bins that align with the global mean residual to keep bin states uniform
    let mean_alignment = (post - mean_residual).abs() * 0.1;

    // Combine: Minimize score
    // post^1.5 creates a non-linear preference for keeping residuals slightly larger 
    // to accommodate future items, while the penalties manage fragmentation.
    let score = post.powf(1.5) + new_bin_penalty + dead_space_penalty + lookahead_penalty + mean_alignment;

