        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Lookahead: Prioritize placements that leave space for the next item.
    // If the next item can fit perfectly into the new post_residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = post_residual - next_item_size;
            // Reward exact fits (zero leftover)
            if diff == 0 {
                score -= 40.0;
            } else if diff < 10 {
                // Penalize "near-misses" that leave a useless sliver
                score += 20.0;
            }
        }
    }

    // 3. Efficiency Balancing: Avoid opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless the number of currently open bins is very low.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Global State Awareness: Use mean_residual to avoid fragmenting the bin population.
    // If our current bin's post_residual is significantly worse than the average, penalize.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Urgency Calibration: As the stream nears the end, prioritize tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 15.0;

    // 6. Last Chance Logic: If this is the only bin that can fit the item, 
    // provide a slight incentive to use it to prevent wasting a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
