pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space left in the bin. 
    // Lower residual is generally better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it's often worse than leaving it empty (0) because it's hard to fill.
    // We penalize values in the (0, 15) range as they are likely wasted.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 * (1.0 - (post_res / 15.0));
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If the current bin's post_residual is smaller than the next item, we penalize it 
    // slightly to encourage saving larger gaps for larger items.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 * (1.0 - progress);
    }

    // Dynamic threshold: As the stream progresses, become more aggressive about 
    // filling bins (Best Fit) and less about leaving room for future items.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // If this is the only bin that fits, prioritize it heavily.
        score -= 50.0 * (1.0 + progress);
    }

    // New bin penalty: If we are considering a brand new bin (bin_residual == bin_capacity),
    // apply a non-linear cost that increases as we approach the end of the stream.
    if bin_residual == bin_capacity {
        score += 40.0 + (30.0 * progress.powf(2.0));
    }

    // Normalize by mean_residual to avoid inflating scores in clusters of empty bins.
    if mean_residual > 0.0 {
        score += (post_res / mean_residual) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Harmonic/Modulo pressure: favor residuals that are multiples of common item sizes (e.g., 20, 25)
    //    to maximize future fitting probability.
    let residual_mod = (post_residual % 20) as f64;
    score += residual_mod * 0.5;

    // 3. Lookahead synergy: If next_item_size is large, favor larger post_residuals.
    //    If next_item_size is small, favor very tight fits (post_residual near 0).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty for stranding the next item (cannot fit)
            score += 50.0;
        } else {
            // Reward for creating a state where the next item fits perfectly
            let diff = (post_residual - next_item_size) as f64;
            score += diff * 0.2;
        }
    }

    // 4. Thresholding: Avoid opening new bins unless necessary
    // If we are forced to open a new bin, penalize it unless the current open bins are "too full" 
    // to accommodate upcoming items (using mean_residual as a proxy for bin health).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one works
            score += 60.0;
        }
        // If no bins fit, new bin is mandatory; set base score to 40.0
        score += 40.0;
    } else {
        // Penalty for creating a bin with very little space left that is hard to use
        if post_residual < 10 && post_residual > 0 {
            score += 15.0;
        }
    }

    // 5. Progression scaling: As we reach the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize "dead space" (post_residual < 10) unless it is a perfect fit.
    // Penalize the creation of new bins unless the current bin state is highly inefficient.

    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the post_residual is in the "unusable" range (1-9),
    // heavily penalize it to force better fits.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If a future item exists, prefer bins where the
    // next item fits comfortably.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
