        } else {
            score += 10.0;
        }
    }

    // 3. Pressure management: If we are forced to open a new bin, penalize it 
    // unless the mean residual is already quite low (suggesting we are wasting space).
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0);
        score -= mean_residual * 0.5;
    }

    // 4. Scarcity handling: If this is the only bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, 
    // become more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize score.
    // Base score is the residual space after placement (Best Fit strategy).
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin prematurely:
    // If this is a new bin (residual == capacity), penalize based on how many 
    // existing bins could have fit this item.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 150.0 + (fitting_bins_count as f64 * 20.0);
    }

    // 2. Lookahead optimization:
    // If there is a next item, we want the post_residual to be as close to 
    // next_item_size as possible (to maximize future packing efficiency).
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward if post_residual is just enough to fit the next item (tight fit).
        if post_residual >= next_item_size {
            score -= (100.0 - diff) * 0.5;
        } else {
            // Penalize if the next item cannot fit in this bin anymore.
            score += 40.0;
        }
    }

    // 3. Global balance:
    // If the post_residual is significantly smaller than the current mean_residual,
    // we are creating a very tight bin, which is generally good for density.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 4. Threshold penalty:
    // Very small residuals are often "dead space" (e.g., < 5). 
    // If we can't fit anything useful, avoid creating these tiny slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // Penalty is lower for smaller post_residual.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // prioritize this bin heavily to avoid fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. New Bin Thresholding: If this is an empty bin (new bin candidate).
    if bin_residual == bin_capacity {
        // Penalize opening a new bin if we have many bins that could fit the current item.
        // As progress increases, we become more conservative (harsher penalty for new bins).
        score += (fitting_bins_count as f64 * 20.0) + (progress * 50.0);
    } else {
        // 4. Fragmentation Control: If post_residual is very small (< 10), it's often wasted space.
        // Penalize "slivers" that are too small to fit typical items.
        if post_residual < 10 {
            score += 15.0;
        }

        // 5. Global State Balancing: Compare this bin's residual to the mean.
        // Prefer bins that are closer to the mean to maintain uniform bin usage.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 6. Last Chance Logic: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: Favor smaller post_residual (Best Fit principle).
    // Penalize large empty spaces created by the placement.
    let mut score = post * 1.5;

    // Penalty for creating 'dead space' that is likely too small for future items.
    // If the post_residual is less than the smallest possible item size (assumed ~10),
    // it is highly undesirable late in the stream.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powf(2.0) * (1.0 + progress * 2.0);
    }

    // Lookahead logic: If the next item cannot fit into the current post_residual,
    // penalize this placement to keep that space available for more compatible items.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += 25.0 * (1.0 - progress);
    }

    // Strategic opening of new bins:
    // If this is a new bin (bin_residual == bin_capacity), only open it if the 
    // current fitting_bins_count is low or if we are early in the stream.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin scales with how many bins are already open.
        score += (open_bins_count as f64 * 5.0) + (1.0 - progress) * 20.0;

        // If there are other bins that could fit the item, strongly discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // Reward placements that bring the bin residual closer to the global mean,
        // promoting uniform packing density.
        let deviation = (post - mean_residual).abs();
        score -= deviation * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize small residuals that cannot accommodate common item sizes.
    // Residuals in the range [1, 9] are "dead zones" for items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Coupling: If the next item is large, favor larger post_residuals.
    // If next_item_size is large (> 50), we want to avoid tight fits now.
    if next_item_size > 50 {
        score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.5;
    }

    // 3. Bin Consolidation: Penalize opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless no existing bins can fit the item (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 120.0;
        } else {
            score -= 10.0; // Reward opening a new bin if we have no choice.
        }
    }

    // 4. Harmonic Alignment: Favor bins where the post_residual is a multiple of 10,
    // as these are more likely to accommodate future items in a uniform distribution.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // 5. Load Balancing: Prevent extreme variance in bin residuals.
    // If the current bin is significantly emptier than the average, favor it to avoid
    // leaving a cluster of very full bins and one very empty bin.
    if (bin_residual as f64) > mean_residual {
        score -= 2.0;
    }

    // 6. Progressive Tightening: As we approach the end of the stream, 
    // prioritize Best-Fit (smaller post_residual) to minimize unused space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
