}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit logic)
    // We favor bins where post_residual is small, but penalize tiny gaps that are unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 45.0; // Heavily penalize "sliver" gaps that are too small for almost any item
    }

    // 2. Lookahead Synergy: If post_residual can fit the next item, heavily reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
