    // 3. Density Balancing: If we are using many bins, prioritize filling existing bins.
    // Use the mean_residual to avoid creating bins that are significantly emptier than current average.
    if (post_residual as f64) > mean_residual {
        score += 15.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // 4. New Bin Threshold:
    // If this is a new bin (bin_residual == bin_capacity), make it expensive unless necessary.
    if bin_residual == bin_capacity {
        score += 40.0; // Base cost to open a new bin

        // If we have other options that can fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 30.0;
        }

        // Late stage optimization: If we are near the end, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 5. Global Efficiency: If fitting_bins_count is 1, this is the only bin that can take it.
    // This is a "forced" placement, so we reduce the cost to ensure we don't skip it to open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
