        // Relax the cost as we approach the end of the stream
        score -= progress * 15.0;
    }

    // 4. Global Density Awareness: If we have many open bins, penalize creating more.
    // Use mean_residual to avoid creating bins that are "too empty" compared to the average.
    if open_bins_count > 0 {
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.2;
    }

    // 5. Critical Constraint: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Fragmentation avoidance: Penalize remainders that are too small to fit any likely item (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
