}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best Fit (minimize post_residual)
    let mut score = post;

    // Penalty for creating "dead zones": if post_residual is smaller than the smallest 
    // likely item (10), it becomes harder to fill later. 
    // We add a penalty that scales with the progress of the stream.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post as f64) * (1.0 + progress * 2.0);
    }

    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    // If the current bin is the only one that fits, we are forced to take it, 
    // but if we have choices, we penalize bins that leave a residual which 
    // prevents the next_item_size from fitting.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Dynamic thresholding for new bins:
    // When bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We penalize this unless the mean_residual of existing bins is already very low,
    // indicating that we are creating fragmentation.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early in the stream, 
        // decreases as we approach the end to allow for cleaner packing.
        score += (bin_capacity as f64 - mean_residual) * (1.5 - progress);

        // If there are other bins that can fit the item, opening a new one is usually bad.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Encourage filling bins that are already "half-empty" to keep the number of 
    // open bins low, weighted by the number of currently open bins.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * (open_bins_count as f64).sqrt() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
