    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= (100.0 - slack) * 1.5;
        } else {
            // Penalty if the current placement prevents the next item from fitting
            // in this bin, forcing a new bin for the next item.
            score += 20.0;
        }
    }

    // 3. Global Efficiency: If this is the last fitting bin, avoid leaving a 
    // very small gap (the "fragmentation trap") unless it's a near-perfect fit.
    if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Distribution Balancing: Penalize opening a new bin if the current 
    // mean_residual is already high (suggesting under-utilization).
    if bin_residual == bin_capacity {
        score += mean_residual * 0.8;

        // Dynamic threshold for opening new bins based on stream progress.
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 10.0;
    }

    // 5. Aggressive Packing: Penalize bins that deviate significantly from 
    // the current mean residual to keep bins at similar fill levels.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize the score.
