    // Dynamic horizon: As the stream progresses, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        score += progress * 20.0;
    }

    // Use mean_residual to balance packing density. 
    // If the mean residual is high, we are under-utilizing bins, so penalize "loose" fits.
    if !is_new_bin && post_residual as f64 > mean_residual {
        score += 5.0;
    }

    // Lookahead/Fitting logic: If this is the only bin that fits, heavily prioritize it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
