        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Quadratic penalty for very small residuals (dead space) that are unlikely to fit future items
    if post_res > 0.0 && post_res < 10.0 {
        score += (10.0 - post_res).powi(2) * 0.8;
    }

    score
}

