    // 3. Global state awareness: If we have many open bins, penalize opening a new one heavily.
    // If we have very few, be more willing to open a new one to keep residuals high in existing bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5) + (mean_residual * 0.5);
    }

    // 4. Strategic consolidation: If this is the only bin that can fit the item, 
    // it is a "must-take" unless the post_residual is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Progress-based scaling: As the stream nears the end, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
