        if mean_residual > 30.0 {
            score += 20.0;
        }
    }

    // 4. Scarcity Adjustment: If this is the only bin that can fit the item, 
    // prioritize it to avoid forced new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // 5. Residual Balancing: Penalize bins that deviate significantly from the mean_residual
    // to keep the packing density uniform across all active bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
