    }

    // Lookahead logic: If the next item is large, avoid leaving a tiny residual in the current bin
    if next_item_size > 0 {
        let lookahead_penalty = if post < next_item_size as f64 {
            (next_item_size as f64 - post) * 0.5
        } else {
            0.0
        };
        score += lookahead_penalty;
    }

    // Dynamic thresholding:
    // As the stream progresses, we become more conservative about opening new bins.
    // If it's a new bin (post == capacity - item_size), add a cost relative to progress.
    if bin_residual == bin_capacity {
