    // The penalty scales with the remaining items in the stream to encourage 
    // packing density early and flexibility late.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (50.0 + (1.0 - progress) * 150.0);

    // Best-Fit Decreasing logic: We want the smallest post_residual (Best Fit).
    // We add a non-linear penalty for larger post_residuals to push towards perfect fits.
    let fit_penalty = post.powi(2) * 0.05;

    // Lookahead coupling: If the next item is large and the current post_residual
    // is too small to accommodate it, we penalize this bin to save it for 
    // smaller items or force a different configuration.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 0.8
    } else {
        0.0
    };

    // If this is the only bin that can fit the item, prioritize it heavily 
    // to avoid unnecessary bin creation (if it's not a new bin).
    let urgency_bonus = if fitting_bins_count == 1 && is_new_bin == 0.0 {
        -40.0
    } else {
        0.0
    };

    // Interaction between mean_residual and progress:
    // As the stream progresses, we want to keep the mean_residual of open bins 
    // tight to maximize remaining capacity.
    let density_pressure = (post - mean_residual) * progress * 2.0;

