pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining capacity. Lower is generally better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "slivers" (unusable space < 10). 
    // We penalize post_residuals that are small but not zero.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // We reward bins that have enough space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - progress);
        } else {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Dynamic threshold: As the stream progresses, become more aggressive 
    // about filling bins tightly to avoid fragmentation.
    let tightness_factor = (mean_residual / bin_capacity as f64) * progress * 10.0;
    score += tightness_factor;

    // Favor using existing bins over opening new ones late in the stream.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Penalize opening a new bin heavily if fitting_bins_count > 0.
        score += 40.0 * (1.0 - progress) + (fitting_bins_count as f64 * 25.0);
    } else {
        // Reward existing bins based on how well they align with the current mean residual.
        score -= (post_res - mean_residual).abs() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // The goal is to minimize score.
