pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin if other bins can fit the item
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 200.0;
    }

    // 2. Best-Fit logic: reward smaller post_residual (tight packing)
    // We already start with post_residual, which inherently rewards tightness.

    // 3. Lookahead Matching: If post_residual is close to next_item_size, we favor this bin
    // to create a "perfect" subsequent fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            // Reward bins that leave exactly enough space for the next item
            score -= (100.0 - diff) * 0.5;
        } else {
            // Penalize if the next item won't fit in this specific bin
            score += 20.0;
        }
    }

    // 4. Entropy control: Avoid creating many bins with very small, unusable residuals
    // If post_residual is small but not zero, it's often a "dead" space trap.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 5. Global Balance: If the current bin's residual is significantly worse than the 
    // average residual of other bins, penalize it to keep open bins balanced.
    if (post_residual as f64) > mean_residual * 1.2 {
        score += 15.0;
    }

    // 6. Progressive constraint: As we near the end of the stream, prioritize 
    // closing bins (lower score) to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    if post_residual == 0 {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is too small for common future items
    // If post_residual is small but not zero, it creates "dead space"
    if post_residual > 0 && post_residual < 15 {
        score += 45.0;
    }

    // Lookahead logic: if next_item fits in post_residual, prioritize this bin highly
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // If this is the only bin that can fit the item, we are forced to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Discourage opening new bins early in the process unless the fit is perfect
    if bin_residual == bin_capacity {
        if progress < 0.8 && post_residual > 20 {
            score += 60.0;
        } else if post_residual == 0 {
            score -= 10.0; // Reward perfect new-bin fit
        }
    }

    // Balance global bin usage: penalize opening too many bins if mean_residual is already high
    if open_bins_count > 0 {
        score += (mean_residual * 0.5);
    }

    // Fine-tuning: favor tighter packing as we approach the end of the stream
    if progress > 0.9 {
        score -= (100.0 - post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating a 'dead zone' (residual space too small for any likely item).
    // If post_residual is small but > 0, it is likely wasted space.
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: If next_item_size is large, favor bins that can accommodate it.
    // If next_item_size > post_residual, the current bin becomes less attractive.
    if next_item_size > 0 {
        if (next_item_size as f64) > post {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: Near the end of the stream, prioritize aggressive packing (lower scores).
    // Early in the stream, avoid small residuals to maintain flexibility.
    let flexibility_penalty = (1.0 - progress) * (bin_capacity as f64 - post) * 0.1;
    score += flexibility_penalty;

    // Favor bins that have a residual close to the mean to maintain uniform bin usage.
    let deviation = (post - mean_residual).abs();
    score += 0.5 * deviation;

    // If this is a new bin, penalize it heavily early on, but reduce penalty as the stream progresses.
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
    }

    // If this is the only bin that can fit the item, give it a significant priority boost.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to prioritize tight packing.
    // 2. Harmonic Class Logic: Reward residuals that are multiples of common item sizes 
    //    or leave space for the lookahead item.
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating "orphaned" space that is too small for most items (below 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // we strongly favor this bin to achieve a "perfect" pair.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // Harmonic alignment: Reward residuals that align with the mean of other bins 
    // to consolidate entropy across the bin set.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // New Bin Thresholding: 
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    // We only open a new bin if the current open bins are "too full" to accept the next item,
    // or if the current packing efficiency is degrading.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0; // Forced to open
        } else {
            // Heavily penalize opening a new bin if an existing one can fit the item,
            // unless the existing bins are extremely crowded (e.g., mean_residual is very low).
            score += 100.0 - (mean_residual * 0.5);
            if next_item_size > 0 && next_item_size < 30 {
                score += 40.0;
            }
        }
    }

    // Capacity constraint: Favor bins that leave room for future items based on 
    // the current progression (early on, keep bins more open; later, pack tightly).
    score += (post_residual as f64) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (gaps < 10 are rarely useful for items >= 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. If this is a new bin, apply a heavy penalty to discourage opening new bins
    // unless the current fit quality is extremely poor.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 0.5);
    }

    // 3. Lookahead: If the next item is large and won't fit in this post_residual, 
    // penalize this placement to keep space for it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. Pressure: If many bins are open, prioritize closing gaps to reduce fragmentation.
    // We reward placements that bring the bin closer to the mean_residual of other bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. If this is the only bin that fits, we are forced to take it; 
    // reduce penalty to ensure it's picked over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Prefer filling bins that are already partially full rather than fresh bins.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Aggressive 2-step lookahead matching.
    // Goal: Minimize post_residual, but prioritize bins that can accommodate the next item (lookahead)
    // or bins that align with the global average residual to prevent fragmentation.

    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin prematurely.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // Heavy penalty for opening new bin if space exists
        } else {
            score -= 20.0; // Slight incentive to open if necessary
        }
    }

    // 2. Lookahead matching: If next_item_size fits in the post_residual,
    // reward this bin to keep the next item packed tightly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Bonus for "perfect fit" with the next item
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 3. Fragmentation control: penalize bins that deviate significantly from the mean_residual.
    // We want to keep residual space uniform across bins to maintain flexibility.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 4. Efficiency scaling based on stream progress.
    // As we reach the end of the stream, prioritize finishing bins over balancing.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late stage: strongly prefer smaller post_residual (Best Fit)
        score += post_residual as f64 * 0.5;
    }

    // 5. Critical Thresholding: If this is the last fitting bin, prioritize it to avoid
    // the penalty of opening a new bin later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) logic: Prefer bins with smaller post-residual (tighter fit).
    // The base score (post_residual) already incentivizes this.

    // 2. Penalty for creating "orphaned" small residuals (fragmentation).
    // If post_residual is small but > 0, it's often unusable for future items (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead optimization: If we have a next item, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the next item perfectly or near-perfectly.
            score -= (bin_capacity - post_residual) as f64 * 0.2;
        } else {
            // Penalize bins that cannot fit the next item if we have other choices.
            score += 15.0;
        }
    }

    // 4. Global state awareness: If we are nearing the end of the stream, 
    // be more aggressive about filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // 5. New Bin logic: Only open a new bin if the current fit is extremely poor.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the current mean residual is already quite low,
        // suggesting that existing bins are too full to accommodate future items effectively.
        if mean_residual > 20.0 && fitting_bins_count > 0 {
            score += 100.0; // Heavily penalize opening new bins if alternatives exist.
        } else {
            score += 40.0; // Moderate cost to open a new bin.
        }
    }

    // 6. Prefer filling bins that are already partially filled (lower mean_residual influence).
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_r = post_residual as f64;
    let cap = bin_capacity as f64;

    // Penalize new bin creation (bin_residual == cap) based on progress.
    // As progress approaches 1.0, we become more conservative about opening new bins.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (50.0 + (50.0 * progress));

    // Best-Fit Decreasing logic combined with lookahead:
    // We prioritize bins that leave the least space (post_r).
    // We penalize bins that leave very small "dead" gaps (e.g., < 10) that are unlikely to fit future items.
    let dead_space_penalty = if post_r > 0.0 && post_r < 10.0 {
        15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Lookahead integration: 
    // If the next item fits into the current post_residual, reward this bin choice.
    let lookahead_reward = if next_item_size > 0 && (post_residual >= next_item_size) {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Coupling: Use mean_residual to balance packing density.
    // If we are significantly above the mean residual, we prefer to pack into tighter bins.
    let density_balance = (post_r - mean_residual).max(0.0) * 0.5;

    // Final score: lower is better.
    post_r + new_bin_penalty + dead_space_penalty + lookahead_reward + density_balance
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that cannot fit typical items (10-30 range)
    // Small residuals are often death traps for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Class Logic: Favor filling bins to specific thresholds (e.g., 25, 50, 75)
    // Modulo check to see if we land on a "clean" capacity fraction.
    let residual_mod = post_residual % 25;
    if residual_mod == 0 {
        score -= 15.0;
    }

    // 3. Lookahead Logic: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 4. Pressure handling: If this is the only fitting bin, penalize the "New Bin" option 
    // unless the residual is extremely bad.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // New bin penalty: Only open if we have no good fits.
            score += 45.0;
        } else {
            // No other choice, normalize to baseline.
            score -= 10.0;
        }
    }

    // 5. Global state normalization: If many bins are open, be more aggressive at packing tight.
    // Scale penalty by the ratio of open bins to the progress of the stream.
    let progress = step_index as f64 / total_items as f64;
    if open_bins_count as f64 > (1.0 - progress) * 20.0 {
        score += (post_residual as f64) * 0.5;
    }

    // 6. Prefer bins that are already "half-empty" to keep the number of active bins low.
    if (bin_capacity - bin_residual) > (bin_capacity / 2) {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
