    // but large enough to waste space. Ranges below 10 are often "unusable".
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy baseline penalty
    // scaled by how many bins are already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 1.5);
    }

    // 3. Lookahead Integration: If the next item is large, prioritize bins that 
    // leave enough space for it (avoiding "blocking" a bin).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }

    // 4. Efficiency Coupling: Favor bins that align with the current mean residual 
    // to keep the bin landscape uniform, reducing variance in bin fullness.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.2;

    // 5. Last Chance Logic: If this is the only bin that can fit the item, 
    // heavily incentivize using it to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progress weighting: As we near the end of the stream, be more aggressive 
    // about filling bins to capacity to avoid trailing orphans.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
