    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 4. New Bin Thresholding:
    // When evaluating a fresh bin (bin_residual == bin_capacity), set a high barrier.
    // Only open a new bin if the current mean_residual is very low (implying we are
