pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    // We want to minimize wasted space (post_residual).
    let mut score = post_res;

    // Penalty for creating a bin that is too "fragile" (very small residual) 
    // when we are early in the stream, to encourage tighter packing later.
    // Exponential penalty for residuals < 10.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res).powf(1.5) * (1.0 - progress);
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin heavily to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // If this is the only bin that can fit the item, we are forced to use it.
    // Lower the score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New bin logic: If we are calling for an empty bin (bin_residual == bin_capacity),
    // we assign a penalty based on how many bins are already open.
    // This discourages opening new bins as the stream progresses.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
        score += (1.0 - progress) * 20.0;
    }

    // Adjust based on the mean residual of existing bins to keep packing density uniform.
    // If our post_residual is much worse than the mean, penalize it.
    if post_res > mean_residual {
        score += (post_res - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
