    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Global State: Penalize opening new bins early in the stream, but allow flexibility near the end.
    if bin_residual == bin_capacity {
        // New bin penalty: scales with progress to allow more bins as the stream concludes
        let new_bin_base_penalty = 35.0 * (1.0 - progress * 0.5);
        score += new_bin_base_penalty;
    }

    // 4. Density Balancing: If we have many open bins, push toward filling the ones with lower residuals.
    if open_bins_count > 0 {
        let residual_diff = (bin_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.15;
    }

    // 5. Urgency: If this is the only bin that fits, prioritize it strongly to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Non-linear scaling for tight fits: Favor bins that leave exactly 0 space.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
