    // waste capacity by opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Coupling with mean_residual: 
    // If our current bin is significantly "better" than the average open bin, 
    // we favor it to keep the distribution of residuals tight.
    if (residual - mean_residual) > 0.0 {
        score += (residual - mean_residual) * 0.1;
    }

    score
