    // Base score is post_residual, which inherently favors tightest fits.

    // 2. Harmonic Class Penalty:
    // Penalize residuals that create "dead zones" (e.g., residues < 10 are usually unfillable).
    if post_residual > 0 && post_residual < 10 {
