    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low (high density)
        // or if we have many open bins already (to prevent spreading items too thin).
        if mean_residual < 15.0 || open_bins_count > 5 {
            score += 40.0;
        } else {
            score += 80.0;
        }
    }

    // 5. Fragmentation Control:
    // If fitting_bins_count is 1, this is the only bin that can take the item.
    // We should heavily prioritize this to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progress Scaling:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
