    // We add a penalty for "wasted" space that is too small for common items (e.g., < 15)
    if post_residual > 0 && post_residual < 15 {
        score += 20.0;
    }

    // 3. Lookahead Matching: If the next item fits perfectly into the post_residual, reward this bin heavily.
    if next_item_size > 0 {
