            score += 5.0;
        }
    }

    // 4. Mean Residual Balancing: Avoid bins that deviate significantly from the average state
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Urgency factor: If only one bin can fit this item, prioritize it to avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 6. Progression scaling: As we approach the end of the stream, prioritize closing bins (tightness)
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
