pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9 range is often a dead zone)
    // We use a smoothed penalty function: exp(-post_res / 5.0) * 100.0
    let fragmentation_penalty = (-post_res / 8.0).exp() * 50.0;

    // Lookahead logic: if next item exists, favor bins that can accommodate both current and next
    let lookahead_penalty = if next_item_size > 0 && (post_residual < next_item_size) {
        25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Favor bins that align with the global mean residual to keep bin levels uniform
    let uniformity_penalty = (post_res - mean_residual).abs() * 0.5;

    // Base score: prioritize Best Fit (lower post_residual)
    // We apply a non-linear scaling to favor tighter fits as the stream progresses
    let base_score = post_res * (1.0 + 0.5 * progress);

    // If this is a new bin (bin_residual == bin_capacity), apply a stiff penalty
    // that decreases as the stream progresses, allowing new bins only when necessary
    let new_bin_penalty = if bin_residual == bin_capacity {
        (80.0 * (1.0 - progress * 0.5)) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // If this is the last chance for the item (only one bin fits), reward it to avoid new bin creation
    let last_chance_bonus = if fitting_bins_count == 1 && bin_residual >= item_size {
        -40.0
    } else {
        0.0
    };

    base_score + fragmentation_penalty + lookahead_penalty + uniformity_penalty + new_bin_penalty + last_chance_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

