    // The base score is post_residual, which inherently favors tightest fits.

    // 2. Harmonic Class Logic: Penalize remainders that are "useless" (too small for common items).
    // Items < 20 are common; if post_residual is in (0, 10), it's highly likely to be dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Synergy: If the next item fits perfectly into the current post_residual,
    // reward this bin heavily to create a "perfect pair".
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = post_residual - next_item_size;
