            // a small sliver of space that can't be used by the lookahead.
            score += 5.0;
        }
    }

    // 4. Thresholding against Open Bins:
    // If this is the ONLY fitting bin, we should be conservative about penalizing it,
    // unless the residual is truly catastrophic.
    if fitting_bins_count == 1 && post_residual < 5 {
        score -= 15.0;
    }

    // 5. New Bin Logic:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only open a new bin if the current open bins are all "bad" fits (e.g., leaving > 30 space).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            // If existing bins are already sparse, opening a new one is a neutral act.
            score += 20.0;
        } else {
            // Otherwise, heavily penalize opening a new bin to force consolidation.
            score += 60.0;
        }
    }

    // 6. Progressive Pressure:
    // As the stream nears the end, become more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
