        score -= 10.0;
    }

    // 5. Global density adjustment: As the stream progresses, prioritize closing bins
    // if the mean_residual is high, to avoid keeping many partially-filled bins open.
    let progress = step_index as f64 / total_items as f64;
    if mean_residual > 30.0 {
        score += progress * 20.0;
    }

    // 6. Final adjustment: Bias against very fragmented bins if we have many open bins.
    if open_bins_count > 5 && post_residual < 15 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "dead space": post_residuals between 1 and 9 are extremely hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If the next item fits into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Pressure management: If this is the only bin that fits the item (fitting_bins_count == 1),
    // heavily incentivize using it to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 4. New bin penalty: If we are considering opening a new bin (bin_residual == bin_capacity),
    // only do it if the existing bins are all "cluttered" (high mean_residual is bad for packing).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score += 30.0;
        // If we have many open bins, penalize opening another one
        score += open_bins_count as f64 * 2.0;
        // If the current mean_residual is low, it means existing bins are full; 
        // opening a new bin is more acceptable.
        score -= mean_residual * 0.5;
    }

    // 5. Efficiency normalization: Prefer bins that result in a tighter fit (lower post_residual)
    // but balance it against the penalty of creating small, useless slivers.
    score += (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals too small to fit typical future items)
    // We penalize residuals that are non-zero but smaller than the minimum likely item (~10)
    if post_residual > 0 && post_residual < 10 {
