    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // 4. Global residual management
    // If current bin's post_residual is significantly better than the mean, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0 * (1.0 - (post_residual as f64 / (mean_residual + 1.0)));
    }

    // 5. New bin penalty
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // unless open_bins_count is very low or fitting_bins_count is 0.
    if bin_residual == bin_capacity {
        score += 40.0;
        if open_bins_count > 0 {
            score += (open_bins_count as f64) * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
