        score -= (50.0 - diff).max(0.0);
    }

    // 3. Balance usage across bins:
    // Penalize bins that are significantly tighter than the current mean residual
    // to prevent fragmenting the packing too early.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 15.0;
    }

    // 4. Decision logic for new bins:
    // If this is an empty bin (new bin candidate), we only pick it if we are forced to 
    // or if the best fit in existing bins is extremely poor (large waste).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 0.0; // Must open a new bin if nothing else fits
        } else {
            // Otherwise, make opening a new bin expensive to encourage consolidation.
            score = 100.0;
        }
    }

    // 5. Final constraint: Favor filling bins that are already partially full 
    // to keep the number of active bins low.
    score += (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize small fragments
    // Fragments between 1 and 9 are extremely hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 - (post_residual as f64 * 4.0);
    }

    // 2. Lookahead Integration: If next item exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can act as a home for the next item
            score -= 25.0;
        } else if post_residual < 10 && next_item_size > post_residual {
            // Penalize creating a dead-end that can't fit the lookahead
            score += 15.0;
        }
    }

    // 3. Dynamic Thresholding: As the stream progresses, become more aggressive with bin packing.
    // Early on, we prefer opening new bins (to keep residuals high). 
    // Later, we force tight packing to minimize the total count.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High penalty for opening a new bin early, decreasing over time.
        score += 30.0 * (1.0 - progress);
    }

    // 4. Global State Awareness:
    // If we have many open bins, penalize opening another one.
    if is_new_bin && open_bins_count > 5 {
        score += 20.0 * (open_bins_count as f64 / 10.0);
    }

    // 5. Fitting Constraint: If this is the only bin that fits the item, 
    // prioritize it significantly to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // 6. Mean Residual Balancing:
    // If this bin's post_residual is significantly lower than the current mean, 
    // it helps "clean up" the average, which is usually good.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let res_f = bin_residual as f64;

    // We prioritize bins that result in a tight fit (low post_residual), 
    // but penalize creating "orphaned" small space (e.g., 1-9) as the stream progresses.
    // We use a non-linear penalty for small residuals when the bin is nearly full.
    let orphan_penalty = if post_residual < 10 && post_residual > 0 {
        (10.0 - post_residual as f64) * 5.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Factor in lookahead: if the next item is large, favor keeping larger bins open.
    // If next_item_size fits in the current post_residual, reward this bin choice.
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Penalize opening a new bin (bin_residual == bin_capacity) unless it's necessary.
    // We scale this penalty by the number of currently open bins to favor consolidation.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 15.0) + (progress * 20.0)
    } else {
        0.0
    };

    // Base score is the remaining space, modified by the interaction of fit efficiency and stream state.
    let mut score = post_res + orphan_penalty + lookahead_bonus + new_bin_penalty;

    // Apply a non-linear coupling: if we are near the end of the stream, 
    // prioritize filling the most empty bins to clear them out (mean_residual coupling).
    if progress > 0.8 {
        score += (res_f - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize configurations that leave very small, unusable slivers (1-9).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Harmonic Packing: Favor bins that leave a residual which is a multiple of common item sizes (e.g., 20, 25).
    // This reduces fragmentation by aligning potential future fits.
    let remainder_mod = (post_residual % 25) as f64;
    score += remainder_mod * 0.4;

    // 4. Density Balancing: If we have many open bins, penalize opening new ones (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
        // Discourage opening new bins early in the stream if fitting options exist.
        if fitting_bins_count > 0 {
