    }

    // 5. Mean Residual Alignment: Avoid bins that deviate significantly from the average occupancy.
    // This keeps the "landscape" of bins uniform, which helps prevent clusters of unusable small bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 6. Last-Chance Logic: If this is the only bin that fits, heavily favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

