    // As we approach the end of the stream, prioritize aggressive packing (tightening)
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base Score: Focus on Best Fit (minimizing post_residual)
    let mut score = post;

    // 2. Penalty for creating "Dead Space" (gaps < 10 are rarely usable)
    // If we leave space between 1 and 9, we penalize it heavily.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 25.0;
    }

    // 3. Pressure for New Bin: Only open if forced or if current fit is extremely poor
    // If this is a new bin (bin_residual == bin_capacity), apply a baseline cost based on open_bins_count.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins early in the stream
        score = 80.0 + (open_bins_count as f64 * 2.0) - (progress * 15.0);
    } else {
        // 4. Lookahead logic: If the next item is large, avoid leaving a tiny post_residual
        // that makes the next item impossible to place.
        if next_item_size > 0 && post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }

        // 5. Global efficiency: Favor bins that stay near the mean residual
        // This helps maintain a uniform packing density across all open bins.
        score += (post - mean_residual).abs() * 0.5;
    }

    // 6. Final constraint: If this is the only bin that fits the item, make it very attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

