    // 2. Best-Fit logic: prioritize small post_residuals (tight packs)
    // We heavily penalize large gaps that are too small for common items (under 10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 3. Lookahead Matching (Aggressive):
    // If the next item fits perfectly into the current post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
