            score += diff * 0.5; // Moderate reward for leaving space for next item
        } else {
            score += 20.0; // Penalty if current choice forces the next item into a new bin
        }
    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that deviate significantly from the current mean usage
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Progression Scaling:
    // Towards the end of the stream, be more conservative about opening new bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.85 && bin_residual == bin_capacity {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalty for opening a new bin: proportional to how many bins are already open
        // and how easily the current item could have fit elsewhere.
        score = 65.0 + (open_bins_count as f64 * 0.5) + (fitting_bins_count as f64 * 15.0);
    } else {
        // Best Fit Decreasing logic: minimize post_residual (already in 'score').
        // Reward filling bins that are already "tight" to keep space for larger future items.
        // If post_residual is very small (near 0), it's a perfect fit.
        if post_residual < 5 {
            score -= 20.0;
        }

        // Lookahead: if the next item is large and won't fit in this post_residual,
        // penalize leaving a "useless" small gap.
        if next_item_size > 0 && next_item_size > post_residual {
            // If we leave a gap that is too small for the next item, penalize it.
            // But only if the gap is significantly wasted (e.g., between 5 and 15).
            if post_residual > 5 && post_residual < 20 {
                score += 15.0;
            }
        }

        // Global state: if we have many bins open, try to consolidate by favoring 
        // bins that have a smaller residual than the global mean.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Dynamic horizon: as we approach the end of the stream, be more conservative
    // about opening new bins.
    if progress > 0.9 && is_new_bin {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post_residual (Best Fit principle)
    let mut score = post;

    // Penalty for opening a new bin:
    // If this is a new bin candidate, add a dynamic threshold penalty based on progress
    // and the current mean residual. Late in the stream, we are more desperate to keep 
    // bins open, so the cost to open a new one increases.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 50.0) + (mean_residual * 0.5);
    } else {
        // Reward bins that leave a residual close to the expected next item size
        // This effectively implements a Best-Fit-Decreasing-like lookahead logic.
        if next_item_size > 0 {
            let diff = (post as i32 - next_item_size as i32).abs() as f64;
            score -= (1.0 / (1.0 + diff)) * 20.0;
        }

        // Penalize fragmentation: If this bin is the only one that fits, 
        // we should prioritize it unless it's a very poor fit.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Non-linear coupling: Exponential penalty for leaving very small, unusable gaps
        // (e.g., gaps < 10 are often "dead space" if min item size is 10)
        if post > 0.0 && post < 10.0 {
            score += (10.0 - post) * 5.0;
        }
    }

    // Favor bins that help reduce the overall mean residual
    score += (post - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
