    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64 * 0.5);
    }

    // 6. Distribution adaptation: If current bin_residual is significantly 
    // larger than the mean_residual, it is a "loose" bin. Penalize using loose bins
    // for small items to preserve them for potentially larger future items.
    if (bin_residual as f64) > (mean_residual + 15.0) && item_size < 30 {
        score += 15.0;
    }

    // 7. Progression scaling: Toward the end of the stream, be more aggressive
    // about filling bins tightly to avoid trailing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
