pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the "New Bin" opening (bin_residual == bin_capacity)
    // We want to force the algorithm to prefer filling existing bins until
    // late in the stream or if the fit is exceptionally poor.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    // Non-linear penalty for opening new bins: 
    // Early in the stream (low progress), penalize new bins heavily.
    // Late in the stream (high progress), allow new bins to avoid fragmentation.
    let new_bin_penalty = is_new_bin * (50.0 + (1.0 - progress) * 150.0);

    // Interaction: If fitting_bins_count is 1, it's the "last chance" bin.
    // If we don't pick it, we must open a new one. 
    // We reward filling this bin to keep open_bins_count low.
    let last_chance_reward = if fitting_bins_count == 1 && is_new_bin == 0.0 { -30.0 } else { 0.0 };

    // Lookahead logic: if the next item is large (e.g., > 50), 
    // we want to preserve space in the current bin if possible.
    let lookahead_penalty = if next_item_size > 50 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 0.5
    } else {
        0.0
    };

    // Base score: prioritize smaller post_residual (Best Fit),
    // but scale it to ensure it doesn't overwhelm the strategic penalties.
    let base_score = post * 1.2;

    // Combine terms
    // We add mean_residual coupling to encourage balancing levels across bins
    let balance_penalty = (post - mean_residual).abs() * 0.2;

    base_score + new_bin_penalty + last_chance_reward + lookahead_penalty + balance_penalty
}

