                score += (next_item_size - post_residual) as f64 * 1.5;
            }
        }

        // 4. Global state balancing
        // If we have many open bins, prioritize filling the ones with the least space to consolidate.
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 5. Dynamic thresholding
    // As the stream nears the end, become more aggressive about filling existing bins to minimize new bin openings.
    if progress > 0.8 {
        score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

