    let mut score = post_res;

    // Penalty for creating "slivers" (dead space < 10):
    // Slivers are hard to fill later, especially as the stream progresses.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 + progress);
    }

    // Lookahead coupling: If next_item_size is large, avoid leaving a residual
    // that is too small to accommodate it.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Dynamic Pressure: As the stream nears completion, favor filling existing bins
    // aggressively to avoid leaving multiple half-empty bins at the end.
    let fill_pressure = (progress * 20.0).exp();
    if fitting_bins_count > 0 && bin_residual < bin_capacity {
        score -= fill_pressure;
    }

    // Bias against opening new bins:
    // If the bin is brand new (residual == capacity), add a high base penalty.
    // This penalty scales with the number of open bins to encourage consolidation.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // Reward bins that have residuals close to the mean_residual of other bins,
    // promoting uniformity in fill rates.
    let residual_diff = (post_res - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
