    // Small residuals (1..9) are often "poison" for future items in 1D bin packing.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Harmonic Class Awareness:
    // If we have a lookahead, favor bins that leave a residual which is a multiple of the next_item_size
    // or perfectly complements the next_item_size to fill the bin.
    if next_item_size > 0 {
        let remainder = post_residual % next_item_size;
        // Reward residual that perfectly fits the next item
        if post_residual == next_item_size {
