    // 3. New Bin Thresholding:
    // If bin_residual == bin_capacity (New Bin Candidate), only open if existing bins are 'crowded'
    // or if the item is too large to fit well into existing open bins.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: base cost scaled by current usage
        score += 45.0 + (open_bins_count as f64 * 0.5);

        // If we have many options, strongly discourage new bins
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Global Load Balancing:
    // Use mean_residual to keep bins roughly at the same fill level.
    // If this bin is significantly emptier than the average, prioritize filling it to 'normalize'.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 5. Progression scaling:
    // Toward the end of the stream, prioritize aggressive packing (Best-Fit)
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
