    // We penalize opening a new bin unless the current open bins are very full.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0; // Must open the first bin
        } else {
            // Penalty for opening a new bin: higher if there are bins that could fit the item.
            score += 30.0 + (fitting_bins_count as f64 * 10.0);
        }
    }

    // 4. Density Balancing: Favor bins with residuals close to the global mean.
    // This encourages uniform filling across the bin set.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Progress weighting: As we approach the end of the stream, prioritize tight packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // Given item sizes are 10-80, residuals < 10 are effectively dead.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Heuristic: Prefer filling bins that are already "tight" to maximize density.
    // We reward placements that result in a lower post-residual, but penalize tiny gaps.
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // Open bin pressure: Penalize opening new bins unless the fit is extremely tight (Best Fit).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5) + 15.0;
    }

    // Lookahead: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual is too small to fit the next item, add a penalty.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Convergence pressure: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    // If this is the only bin that fits, prioritize it heavily to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

