    }

    // 5. Progression Weighting: As the stream nears completion, prioritize closing bins
    // by penalizing empty space more aggressively
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.8;

    // 6. Avoid "Dead Space" creation: If post_residual is too small to fit any common item (e.g., < 10),
    // it is often better to have a larger residual that can fit something.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
