    // Penalty for opening a new bin: Only do this if the fit is truly terrible or we are near the end.
    if is_new_bin {
        // High base penalty for opening a new bin, mitigated by progress (near end, we care less about bin count).
        score += 45.0 * (1.0 - progress * 0.5);
    } else {
        // Reward for leaving space that can accommodate the next item (Lookahead).
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0; // Strong reward for fitting the next item
            } else if post_residual > 0 {
