    // the most flexible residual relative to the current mean.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 5.0; // Priority to "last chance" bins to avoid opening new ones
    }

    // Global state adjustment: Avoid creating bins with residuals far from the global mean
    // to keep bin utilization uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Penalize creating "dead zones" (very small residuals < 5) unless it's a perfect fit.
    if post_residual > 0 && post_residual < 5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalty for empty bin usage: 
    // We increase the cost of opening a new bin as the stream progresses,
    // forcing higher utilization density in later stages.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 
        25.0 + (35.0 * progress) 
    } else { 
        0.0 
    };

    // Best-Fit Decreasing logic: 
    // We favor bins where the remaining space (post) is minimized.
    // However, we penalize "near-empty" remaining space (e.g., 1-5 units) 
    // which are notoriously hard to fill later.
    let dead_space_penalty = if post > 0.0 && post < 8.0 {
        (8.0 - post) * 5.0
    } else {
        0.0
    };

    // Lookahead coupling:
    // If we know the next item, we penalize current placements that leave 
    // insufficient room for the next item, unless it's the last chance.
    let lookahead_penalty = if next_item_size > 0 && fitting_bins_count > 1 {
        if post < next_item_size as f64 {
            15.0 * (1.0 - progress)
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Global state coupling:
    // Penalize increasing the number of bins if the mean residual is already high.
    let fragmentation_penalty = (open_bins_count as f64 * mean_residual) / 10.0;

    // Final score: lower is better.
    // We combine the primary best-fit (post) with non-linear penalties.
    post + new_bin_penalty + dead_space_penalty + lookahead_penalty + fragmentation_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

