        }
    }

    // 5. Harmonic Class Alignment: Favor filling bins such that the post_residual 
    // aligns with common divisors of the capacity (100: 20, 25, 50)
    let remainder = post_residual % 20;
    if remainder == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // 6. Progression Scaling: As the stream nears the end, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
