    // Try to pack items into bins that bring them closer to the mean to consolidate space.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // Last chance logic:
    // If this is the only bin that fits the current item, prioritize it heavily
    // to avoid unnecessary bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Non-linear scaling based on current open bin density:
    // Penalize higher open_bins_count to encourage tighter packing in fewer bins.
    score += (open_bins_count as f64).powf(1.2) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Lookahead logic: if next_item_size fits in the post_residual, reward this bin heavily
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
        // Further reward if the post-post residual is small (tight packing)
        let secondary_residual = post_residual - next_item_size;
        score += secondary_residual as f64 * 0.2;
    }

    // 3. Penalty for opening new bins prematurely
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing bin can take the item
            score += 150.0;
        } else {
