    }

    // 4. Harmonic class affinity: favor filling bins to specific thresholds (e.g., 100, 50, 33)
    // Small residuals are usually good, but very small residuals (1-5) can be "dead space"
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    // 5. Global state pressure: if many bins are open, be more aggressive about filling them
    let progression = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 - progression) * 2.0;

    // 6. Prefer bins that are already closer to the mean residual to maintain uniform distribution
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but punish post_residuals that are too small to fit common items
    // (dead space) and penalize opening new bins unless necessary.

    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is between 1 and 9, it's highly likely to be wasted
    // as items are >= 10. Heavily penalize this "unusable" gap.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead optimization: If the next item can fit in the current post_residual, 
