    if bin_residual == bin_capacity {
        // Only consider a new bin if we have many open bins already or if it's the only option.
        score += (open_bins_count as f64) * 2.5;

        // If we have other bins that could fit this, penalize the new bin heavily.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Global efficiency: Favor bins that align with the current mean residual
    // to maintain a consistent density across the packing set.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin: bias against new bins unless residuals are poor
    if bin_residual == bin_capacity {
