    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 60.0 + (progress * 40.0);
        } else {
            // If no other bin fits, this is a necessary evil; reduce the penalty.
            score -= 10.0;
        }
    }

    // 5. Reward tight fits (Best-Fit principle):
    // Smaller post_residual is generally better, but we modulate it by the global mean.
    score += (post_residual as f64 / (mean_residual + 1.0)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) using progress-weighted threshold
    // As the stream progresses, we become more conservative about opening new bins.
    let new_bin_penalty = if bin_residual == bin_capacity {
        25.0 + (progress * 50.0)
    } else {
        0.0
    };

    // Calculate how well this bin aligns with the next item (lookahead synergy)
    // If next_item_size fits in the post_residual, reward this bin choice.
    let synergy = if next_item_size > 0 && next_item_size <= post_residual {
        -15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Penalize creating "fragmented" space (very small residuals that are hard to fill)
    // We target residuals that are either 0 (perfect fit) or large enough to hold typical items.
    let fragmentation_penalty = if post_res > 0.0 && post_res < 10.0 {
        20.0 * (1.0 - (post_res / 10.0))
    } else {
        0.0
    };

    // Coupling: Favor bins with lower residuals, but adjust based on the current mean_residual.
    // If this bin's post_residual is significantly better than the global mean, reward it.
    let mean_bias = (post_res - mean_residual).clamp(-10.0, 10.0);

    // Final score: lower is better. 
    // We prioritize small post_residuals (Best Fit) modified by lookahead and fragmentation heuristics.
    let score = post_res + new_bin_penalty + synergy + fragmentation_penalty + mean_bias;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
