            let threshold = 15.0 + (progress * 20.0);
            if mean_residual > threshold {
                score += 50.0; // Heavily penalize opening new bins unless necessary
            }
        }
    } else {
        // 4. Global State Coupling:
        // Reward placing in bins that are already "half-full" to keep global mean residual stable.
        let utilization = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= (utilization * 10.0);

        // 5. Scarcity Penalty:
        // If this is the last bin that can fit the item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

