    }

    // New Bin Logic: Discourage opening a new bin unless the current fit is extremely poor
    // or we are nearing the end of the stream and need to consolidate.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high, but decreases as we reach the end of the stream
        // to encourage finishing packed bins.
        score = 45.0 + (20.0 * progress);

        // If we have many bins open, penalize opening another one
        score += (open_bins_count as f64) * 2.0;
    }

    // Pressure to use bins that are already "half-empty" to keep them balanced
    // (mean_residual coupling)
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * deviation * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
