    // the current bin is a "perfect fit" (post_residual == 0).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if open_bins_count > 0 {
            // Heavily penalize new bin unless it's a perfect fit or no other bin can take it
            if post_residual > 0 {
                score += 40.0 + (mean_residual * 0.5);
            }
        }
    } else {
        // 4. Prefer bins that are already "fuller" (Best Fit logic)
        // Lower post_residual means higher fill rate.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;

        // 5. If this is the last chance to fit an item in an existing bin, favor it.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 6. Progress-based refinement: As the stream nears the end, become more aggressive 
    // with bin packing to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

