    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for any future item
    // If post_residual is small (e.g., < 10), it's likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead matching: reward bins where the post_residual can accommodate the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit scenario: highly desirable
            score -= 40.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Bad fit: the next item will definitely force a new bin or a different bin
            score += 15.0;
        }
    }

    // 3. Balance usage across existing bins (load balancing)
    // Avoid creating too many bins by penalizing the "new bin" choice if open_bins_count is high
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // Discourage opening new bins early if we have space in existing ones
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // 4. Tightness objective: Favor bins that stay close to the mean residual
    // This keeps the packing density uniform across all active bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 5. Progression adjustment: Be more conservative with new bins as the stream nears completion
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

