    // Best fit (lowest residual) is generally preferred.
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // If post_residual is > 0 and < 10, it's a "sliver" penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if we know the next item, penalize bins that can't fit it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
