    }

    // Global state awareness: 
    // If we have many open bins, we should be more aggressive in filling existing ones (higher penalty for new bins).
    if is_new_bin {
        score += 30.0 + (open_bins_count as f64 * 2.0);
        // Late-stage optimization: if near end, be more willing to use new bins to avoid stranding items.
        score -= progress * 20.0;
    } else {
        // If this is the only bin that fits, prioritize it strongly
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Balance against the mean residual of the system to keep bin usage uniform.
    if !is_new_bin {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
