    let mut score = post_res;

    // Penalty for creating "slivers" (unusable space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if next_item fits in the current post_residual, reduce score (reward)
    if next_item_size > 0 && post_residual >= next_item_size {
