    }

    // Interaction with mean_residual: avoid placing items in bins that are significantly 
    // more empty than the average, to maintain "packing density" homogeneity
    let res_deviation = (bin_residual as f64 - mean_residual).abs();
    score += res_deviation * 0.1;

    // Favor bins that are the "last chance" (fitting_bins_count == 1) to avoid 
    // leaving a bin with high residual space unused
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

