    // We penalize large post_residuals exponentially to favor tight packing.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Reward residuals that are multiples of common item sizes
    // or leave space for the next item in the stream.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for "perfect match" pairs
            score -= (next_item_size as f64) * 2.0;
        } else {
            // Penalize leaving a gap too small for the next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // 3. Fragmentation Penalty: Penalize bins that leave "useless" slivers (less than 10).
    // These are unlikely to accommodate future items (min size ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Thresholding: If this is the last fitting bin, we avoid opening a new bin 
    // unless the fit is extremely poor, by heavily discounting the current bin score.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. New Bin Constraint: When evaluating a brand new bin (residual == capacity),
    // we apply a high cost to discourage opening it unless all existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 35.0; 

        // As the stream progresses, make it slightly easier to open new bins to 
        // prevent late-stage fragmentation.
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 10.0;
    }

    // 6. Mean Residual Balancing: Avoid bins that deviate significantly from the 
    // average state of the system to maintain uniform packing pressure.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Strict dead space avoidance with bin pressure management.
    // We aim to minimize post_residual (Best Fit) while heavily penalizing "unusable gaps" 
    // (gaps < 10, the minimum item size) and managing open bin proliferation.

    let mut score = post_residual as f64;

    // 1. Penalty for creating unusable dead space (gaps < 10).
    // This forces the algorithm to prefer bins that leave larger, more useful remnants.
    if post_residual > 0 && post_residual < 10 {
