    // If the next item cannot fit in the current post_residual, apply a moderate penalty.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // 4. Global bin pressure: If we have many open bins, become more aggressive 
    // about filling the current bin to consolidate space (lower score = higher priority).
    if open_bins_count > 5 {
