    // 4. Fitting Constraint: If this is the only bin that fits the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Efficiency: If current mean residual is high, prioritize filling
    // existing bins to consolidate space.
    if mean_residual > 40.0 && bin_residual != bin_capacity {
        score -= 10.0 * (post_residual as f64 / 100.0);
