    }

    // 5. Final constraint:
    // If this is the last chance for the item to fit in an existing bin, 
    // prioritize it to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
