pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny, unusable gaps (dead space)
    // The "sweet spot" for post_residual is 0 (perfect fit) or > 10 (leaving room for future items)
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        (10.0 - post_residual as f64) * 5.0
    } else {
        0.0
    };

    // Factor in the lookahead: if the next item is large, favor bins that keep more space
    let lookahead_impact = if next_item_size > 0 {
        let needed = next_item_size as f64;
        if post_res < needed {
            // If the current placement makes the next item impossible to fit, add a penalty
            15.0 * (1.0 - progress)
        } else {
            // If it still fits, reward the bin for being "large enough"
            -5.0 * progress
        }
    } else {
        0.0
    };

    // Bias against opening new bins early in the stream
    let new_bin_bias = if bin_residual == bin_capacity {
        (1.0 - progress) * 40.0 + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Heuristic: Minimize post_residual (Best Fit), but adjust for future needs
    // We want post_residual to be small, but not so small it creates dead space
    let base_score = post_res + dead_space_penalty + lookahead_impact + new_bin_bias;

    // Adjust score based on how many other bins could fit this item
    // If fitting_bins_count is high, we are less desperate to use this specific bin
    let competition_factor = if fitting_bins_count > 1 {
        (fitting_bins_count as f64).ln() * 2.0
    } else {
        0.0
    };

    base_score + competition_factor
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
