    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into this post_residual, 
    // highly reward this bin (Best-Fit-Lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (100.0 - (post_residual - next_item_size) as f64) * 0.5;
    }

    // 3. Open Bin Pressure: If this is a new bin, penalize it based on how many 
    // bins are already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 4. Fitting Constraint: If only one bin can fit this item, prioritize it 
    // to keep the bin count minimal and prevent forced new bins later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Efficiency: If the current post_residual is significantly worse 
    // than the current average residual, penalize it to encourage tighter packing.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

