    if post_residual > 0 && post_residual < 6 {
        score += 20.0;
    }

    // 5. New-bin thresholding: Discourage opening a new bin unless the existing
    // fits are extremely poor (i.e., they leave very little room for future items).
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is very high (already wasting space)
        // or if we are very early in the process.
        if mean_residual < 25.0 && step_index > (total_items / 10) {
            score += 50.0;
        } else {
            score += 5.0;
        }
    }

    // 6. Global capacity pressure: As the stream progresses, prioritize closing 
    // bins (lower mean_residual) to keep the packing density high.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'unusable' gaps (dead space < 10 units, assuming 10 is min item size)
    // If post_residual is in [1, 9], it is highly likely to remain empty.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if next item exists, penalize bins that cannot fit it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Pressure to consolidate: penalize opening new bins unless necessary
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one could fit the item
            score += 100.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Reward for opening a new bin only when strictly required
            score -= 10.0;
        }
    }

    // Heuristic: Prefer bins that bring the bin_residual closer to the global mean
    // This promotes uniform filling across the bin set
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // Favor bins that are 'tighter' after placement (Best Fit principle)
    // post_residual is already part of the base score, but we add a weight 
    // to ensure we prefer smaller post_residual values
    score += (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We want the post_residual to be as close to 0 as possible.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead matching: If the next item fits into the post_residual, 
    // significantly reward this bin to keep the next item "tucked away".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
        // Further reward if the resulting space after the next item is very small
        let remaining_after_next = (post_residual - next_item_size) as f64;
        score += remaining_after_next * 0.5;
    }

    // 3. Penalty for fragmentation: If the post_residual is too small to be useful
    // for most items (e.g., < 10), it becomes "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. Mean-Residual Balancing: If this bin is significantly emptier than the average,
    // prioritize filling it to keep the average uniform.
    if (bin_residual as f64) > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.8;
    }

    // 5. New-Bin Thresholding: If we are forced to open a new bin, make it expensive
    // unless the current open bins are all very poor fits.
    if bin_residual == bin_capacity {
        score += 45.0; // Base cost to open a new bin
        // If there are already many open bins, penalize opening more heavily.
        score += (open_bins_count as f64) * 2.0;
    } else {
        // If this is the only bin that fits, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 6. Progression scaling: As we approach the end of the stream, 
    // become more aggressive in packing to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score: prioritize tightest fit (Best-Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating "dead space" (gaps < 10 are rarely useful given item range)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Lookahead logic: if next item exists, penalize leaving a bin that can't fit it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Global state awareness: if we are near the end of the stream, prioritize closing bins
    // If few bins are open, try to pack tighter even if it creates small gaps
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Dynamic threshold for opening a new bin
    // If residual is large, we are looking at a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is already quite tight
        // or if we have many bins open and need to spread items
        score = 45.0 + (mean_residual * 0.5) - (progress * 10.0);
    } else {
        // If we are placing in an existing bin, adjust based on how much space we leave
        // relative to the average state of the system
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin heavily as the stream progresses, 
    // unless the residual is very small (perfect fit).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 50.0 + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Calculate a "tightness" score: punish post_residual values that are
    // too small to accommodate common subsequent items (dead space creation).
    // We favor post_residuals that are either near 0 or large enough for the next item.
    let lookahead_penalty = if next_item_size > 0 {
        if post < next_item_size as f64 {
            (next_item_size as f64 - post).powf(1.5)
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Reward bins that have residuals close to the global mean, 
    // promoting uniform bin utilization.
    let mean_alignment = (post - mean_residual).abs() * 0.5;

    // Combine factors:
    // 1. post: Best-Fit (lower is generally better)
    // 2. new_bin_penalty: Discourage new bins late in the stream
    // 3. lookahead_penalty: Avoid "orphaning" small spaces
    // 4. mean_alignment: Encourage balance
    let score = post + new_bin_penalty + lookahead_penalty + mean_alignment;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the least space (lower post_residual).
    // 2. Harmonic Class Penalty: heavily penalize post_residuals that are too small to fit common item sizes (e.g., < 20).
    if post_residual > 0 && post_residual < 20 {
        score += 45.0;
    }

    // 3. Lookahead synergy: if the next item fits into the current post_residual, reduce the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 4. Threshold Management: If we are nearing the end of the stream, force tighter packing.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (bin_residual as f64) * 0.2;
    }

    // 5. New Bin Constraint: Only open a new bin if the current bin is "too full" to be useful for future items,
    // or if the current bin fit is significantly worse than the average.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // High penalty for opening new bins unless necessary
            score = 150.0 + (mean_residual * 0.5);
        }
    } else {
        // Penalty for using a bin that is already very full when a better fit might exist
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // 6. Harmonic balance: penalize creating bins that are slightly over half-full (the "awkward" zone)
    if post_residual > 40 && post_residual < 60 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

