    // This forces the algorithm to pack items into bins that are already "tight"
    if (post_residual as f64) < mean_residual * 0.8 {
        score -= 10.0;
    }

    // 5. Last Chance Heuristic: If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
