    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We penalize larger post_residuals heavily.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Synergy: If the post_residual can accommodate the next item, 
    // prioritize this bin to reduce fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Last Chance Logic: If this is the only bin that fits, we are forced to accept it.
    // Lower the score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 4. New Bin Thresholding: If we are evaluating a new bin (residual == capacity),
    // we make it expensive to discourage early bin creation.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Dynamic scaling: as we progress through the stream, become more conservative.
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 5. Mean Residual Balancing: Penalize bins that deviate significantly from the mean 
    // to keep the "average" bin quality consistent.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
