    // 4. Harmonic/Fractional weight: Favor bins that leave a residual which is a multiple 
    // of common item sizes, reducing fragmentation.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 5. Open bin management: If this is the last fitting bin, prioritize it to avoid 
    // opening a new bin unnecessarily (unless the fit is extremely poor).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 6. Global state influence: As the stream progresses, discourage opening new bins 
    // by applying a progress-dependent penalty to the "new bin" case (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Increase penalty for new bins as we reach the end of the stream
        score += 40.0 * (1.0 + progress);

        // Also penalize new bins if we have many already open bins
        score += (open_bins_count as f64) * 2.0;
    }

    // 7. Balance residual: Discourage bin choices that deviate significantly from the mean 
    // residual of existing bins to keep bin utilization uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
