        }
    }

    // 4. Mean Residual Balancing: Avoid bins that deviate significantly from the mean
    // to keep the fill-rate homogeneous across the open bin set.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Progression scaling: As we reach the end of the stream, be more aggressive
    // about filling bins to reduce the final open_bins_count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
