    if bin_residual == bin_capacity {
        // Only consider a new bin if the average space in existing bins is very low
        // and we are not near the end of the stream.
        score += 40.0 + (mean_residual * 2.0) - (progress * 20.0);
    }

    // Penalty for leaving "unusable" gaps: If the post_residual is small but 
    // larger than 0, it creates "dead space" that cannot fit common small items.
    if post > 0.0 && post < 10.0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
