        score -= 45.0 * (1.0 - progress);
    }

    // 3. Fragmentation Avoidance:
    // Penalize post_residual ranges that are too small to fit any likely future items (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 4. Global State Balancing:
    // If we have many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Strong penalty for opening a new bin if others exist.
            score += 60.0 + (mean_residual * 0.5);
        }
    } else {
        // If it's an existing bin, reward using bins that are already 'fuller' 
        // compared to the mean of all open bins.
        if (bin_capacity - bin_residual) as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // 5. Scarcity Constraint:
    // If this is the only bin that can fit the item, prioritize it to prevent 
    // forcing a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 6. Dynamic Scaling:
    // As the stream progresses, prioritize closing bins (tighter fit) over flexibility.
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) increasingly as the stream progresses.
    // This forces tighter packing early on and prevents fragmentation later.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (50.0 + (progress * 150.0));

    // Best-Fit Decreasing logic: penalize large post_residuals (wasted space).
    // We add a non-linear quadratic term to heavily penalize "half-filled" bins (post_residual ~ 50).
    let waste_penalty = (post * post) / 20.0;

    // Lookahead coupling: if the next item is large, penalize small residuals in the current bin
    // to keep space available for future items.
    let lookahead_pressure = if next_item_size > 0 {
        let fit_next = if post_residual >= next_item_size { 0.0 } else { 1.0 };
        fit_next * (next_item_size as f64 * 0.5)
    } else {
        0.0
    };

    // Reward bins that have residuals close to the current mean_residual, 
    // encouraging uniform filling across all open bins.
    let deviation_from_mean = (post - mean_residual).abs();
    let uniformity_reward = -1.5 * (100.0 - deviation_from_mean).sqrt();

    // Final score: lower is better.
    // We subtract the uniformity_reward and add the penalties.
    post + new_bin_penalty + waste_penalty + lookahead_pressure + uniformity_reward
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'fragmentation': post_residual values that are small (1-9) 
    // are often unusable for future items (10-100).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Lookahead logic: if the next item can fit into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // Harmonic preference: Favor bins that leave a residual which is a multiple of larger items
    // to keep the bin 'useful' for common item sizes.
    let harmonic_fit = (post_residual % 25) as f64;
    score += harmonic_fit * 0.5;

    // Density normalization: If we have many open bins, penalize opening a new one heavily.
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0; // Must open a bin if none are available
        }
    }

    // Progression awareness: As we approach the end of the stream, prioritize emptying 
    // existing bins over starting new ones (reduce new bin score).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 20.0;
    }

    // Penalize bins that deviate significantly from the mean residual of open bins
    // to encourage uniform packing (Best Fit strategy).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals (< 10) are usually unusable for future items (10..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Heuristic: If we are forced to open a new bin (bin_residual == bin_capacity), 
    // penalize it based on how many bins are already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // Lookahead logic: If the next item exists, penalize bins that cannot fit the next item 
    // after placing the current one, but only if we have few fitting options.
    if next_item_size > 0 && post_residual < next_item_size {
        if fitting_bins_count > 1 {
            score += 20.0;
        }
    }

    // Favor bins that bring the residual closer to the mean_residual to keep bin distribution uniform
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // Progression weight: In late stages, prioritize filling bins completely to close them out
    let progress = step_index as f64 / total_items as f64;
    score -= (1.0 - progress) * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize near-empty bins
    // if a better fit is available elsewhere.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: base cost is high.
        // We only open a new bin if the current mean_residual is already very tight.
        score = 85.0 + (mean_residual * 0.5);
    } else {
        // Reward bins that leave very little space (Best Fit)
        // Penalty for leaving "dead" space that is too small for common items (e.g., < 10)
        if post_residual < 10 {
            score -= 20.0;
        }

        // 2. Lookahead Synergy: If the next item fits perfectly into the post_residual
        // we reward this bin heavily to keep the future item's slot open.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 45.0;
            } else if post_residual > next_item_size {
                // Reward bins that keep enough space for the next item
                score -= 10.0;
            } else {
                // Penalize bins that become "orphaned" (too small for the next item)
                score += 15.0;
            }
        }
    }

    // 3. Pressure Management: As we approach the end of the stream, 
    // prioritize clearing out open bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (open_bins_count as f64);

    // 4. Fitting Constraint: If this is the last available bin that can fit the item,
    // we should prioritize using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the residual space left after placement.
    // Minimizing this is the Best Fit objective.
    let mut score = post_residual as f64;

    if is_new_bin {
        // Penalize opening a new bin heavily unless we are in the final phase of the stream
        // or the current mean residual is already very low (fragmentation is high).
        score += 45.0 + (mean_residual * 0.5) - (progress * 20.0);
    } else {
        // If this bin is the only one that can fit the item, prioritize it to avoid new bin creation.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Lookahead: if the next item is large, avoid leaving a residual that is just slightly
        // too small for it (the "gap trap").
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // If it doesn't fit, this is a "dead" residual zone for the next step.
                // Penalize if the residual is small but useless.
                if post_residual > 5 {
                    score += 15.0;
                }
            } else {
                // If the next item fits, reward this placement.
                score -= 10.0;
            }
        }

        // Dynamic adjustment: As we approach the end of the stream, prioritize 
        // tighter packing to close out bins.
        score += (post_residual as f64) * progress;
    }

    // Apply a penalty based on how many bins are already open to favor consolidation.
    score += (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize tighter fits (Best-Fit principle)
    // We penalize larger post_residuals to encourage filling bins compactly.
    let mut score = post * post;

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), we add a high cost.
    // This cost decreases as the stream progresses (to prevent bin waste at the end).
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 5000.0 + (open_bins_count as f64 * 100.0);
    } else {
        // Influence of lookahead:
        // If next_item_size is large and fits in this bin, prioritize keeping it open.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= (next_item_size as f64) * 50.0;
        }

        // Penalty for creating 'dead space' that is too small for common items (e.g., < 15)
        if post_residual < 15 && post_residual > 0 {
            score += 200.0 * (1.0 + progress);
        }
    }

    // Dynamic adjustment based on fitting_bins_count:
    // If this is the only bin that can fit the item, lower the score to prioritize it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 1000.0;
    }

    // Interaction with mean_residual: 
    // Penalize bins that deviate significantly from the current average packing density.
    let deviation = (post - mean_residual).abs();
    score += deviation * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Small post_residuals are usually good, but near-zero gaps 
    // are often "dead space" if they are too small to fit future items.
    // Penalize gaps that are smaller than the smallest likely item (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 - (post_residual as f64);
    }

    // 2. Harmonic Lookahead: If the next item fits into the current post_residual, 
    // prioritize this bin highly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Fitting Bin Constraint: If this is the only bin that fits the current item, 
    // heavily incentivize picking it to avoid opening a new bin (if not already new).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. New Bin Logic: If we are considering a new bin, penalize it based on how many
    // open bins are already available. Opening a new bin is a last resort.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 10.0;
        // If we are early in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 20.0;
    }

    // 5. Mean Residual Balancing: Avoid creating bins that are significantly 
    // emptier than the current average of open bins.
    if bin_residual != bin_capacity {
        let deviation = (bin_residual as f64) - mean_residual;
        if deviation > 15.0 {
            score += deviation * 0.5;
        }
    }

    // 6. Harmonic Modulo Coupling: Favor placements that result in post_residuals 
    // that are multiples of common item sizes (e.g., 20, 25, 50).
    if post_residual > 0 {
        if post_residual % 25 == 0 {
            score -= 5.0;
        } else if post_residual % 20 == 0 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Avoidance: Penalize gaps that are too small to fit common items (10-25 range).
    // If post_residual is in the "danger zone" (1..10), it's highly likely to become permanent waste.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize bin density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 3. Bin Pressure: Penalize opening new bins when many bins are already open.
    // If this is a new bin (bin_residual == bin_capacity), increase its cost 
    // proportionally to the current open bin count to favor consolidation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
    }

    // 4. Tight Fit Reward: Heavily favor bins that result in a near-zero residual.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 5. Mean Residual Balancing: If the bin's post_residual is significantly better 
    // than the global mean of open bins, reward the placement to drive down average waste.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 6. Last Chance Logic: If this is the only bin that fits the item, 
    // reduce penalty to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward this bin.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward configurations where the remaining space can accommodate the upcoming item.
        if post_residual >= next_item_size {
            score -= (100.0 - diff) * 0.5;
        } else {
            // Penalty if the lookahead item is forced into a new bin.
            score += diff * 0.2;
        }
    }

    // 3. Mean Residual Balancing: Avoid creating bins that deviate significantly from the average fullness.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 4. Scarcity/Urgency: If this is the only bin that fits the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. New Bin Thresholding: Discourage opening new bins unless the current best fit is extremely poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already high (bin cluttering).
        if mean_residual < 30.0 {
            score += 40.0;
        } else {
            score += 15.0;
        }
    }

    // 6. Progressive packing: Prefer filling existing bins as the stream nears completion.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize new bin creation (bin_residual == bin_capacity)
    // We make it expensive early on, but potentially necessary if fitting_bins_count is low.
    if bin_residual == bin_capacity {
        score += 35.0 + (progress * 25.0);
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 2. Best-Fit logic: Penalize large post_residuals (dead space)
    // We prefer post_residual to be small (near 0) or large enough to fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent fit: This bin can accommodate the next item.
            score -= 15.0;
        } else if post_residual > 0 && post_residual < 15 {
            // Bad fit: Small sliver left that is likely unusable.
            score += 20.0;
        }
    }

    // 3. Global state awareness:
    // If mean_residual is high, we have plenty of room, so be pickier about filling bins tightly.
    // If mean_residual is low, we are running out of space, prioritize fitting.
    if mean_residual < 20.0 {
        score -= (20.0 - mean_residual) * 0.5;
    }

    // 4. Tightness bias:
    // Reward bins that become very full (Best-Fit Decreasing intuition).
    if post_residual < 10 {
        score -= 10.0;
    }

    // 5. If this is the last chance for the current item, lower the penalty for a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let residual_f = post_residual as f64;

    // Penalize small residuals (fragmentation) more heavily as the stream progresses
    // to encourage tighter packing in later stages.
    let fragmentation_penalty = (1.0 - (residual_f / bin_capacity as f64)) * progress * 50.0;

    // Reward placing items in bins that bring the bin closer to the global mean residual,
    // reducing variance in bin fullness.
    let mean_alignment = (residual_f - mean_residual).abs() * 0.5;

    // Lookahead logic: if we have a large next item, prioritize keeping space open.
    // If next_item_size is large, we penalize bins that leave behind a "dead zone" (1-10 space).
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 2.0
    } else {
        0.0
    };

    // Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a baseline cost.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_cost = if is_new_bin {
        // Only open new if fitting_bins_count is low or current bins are very full.
        (fitting_bins_count as f64 * 10.0) + (1.0 - progress) * 20.0
    } else {
        0.0
    };

    // Base score is the post_residual (Best Fit principle).
    // We modify it with the non-linear factors calculated above.
    let mut score = residual_f + fragmentation_penalty + mean_alignment + lookahead_penalty + new_bin_cost;

    // Boost score (lower value) for bins that are becoming "perfect" fits (near zero residual).
    if post_residual < 5 {
        score -= 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best Fit (minimize post_residual).
    // 2. Penalty for creating "fragmented" small space:
    // If post_residual is in the range [1, 9], it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Harmonic Lookahead: If the next item fits into the current post_residual,
    // prioritize this bin to prepare for a "perfect" packing sequence.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Further reward if it leaves very little space after the next item.
        let residual_after_next = post_residual - next_item_size;
        if residual_after_next < 5 {
            score -= 15.0;
        }
    }

    // 4. Harmonic Class Logic:
    // If the current bin is empty (new bin candidate), only select it if the 
    // current item is large (e.g., > 60) or if we have no good fits (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing options.
            score += 100.0;
        }
        // If it's a large item, make the new bin more attractive.
        if item_size > 70 {
            score -= 30.0;
        }
    }

    // 5. Global Balancing:
    // Avoid leaving all bins with very small residuals (which creates fragmentation).
    // If our post_residual is closer to the mean_residual of other bins, 
    // we encourage cluster packing.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Progression scaling:
    // As we approach the end of the stream, prioritize tight packing more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
