    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // Threshold for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), set a high baseline cost
    // so we only open it if the existing fits are objectively terrible (high post_residual)
    if bin_residual == bin_capacity {
        // Higher threshold for opening a new bin as the stream progresses
        let progress = step_index as f64 / total_items as f64;
        score = 45.0 + (progress * 15.0);
    } else {
        // If it's the last fitting bin, slightly reward to keep bin density high
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    // Favor bins that leave larger residues for future items (Best Fit variant)
    // We subtract post_residual scaled to prioritize tight fits
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We heavily penalize post_residual in the range [1, 9] as items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0 / (post_residual as f64 + 0.1);
