    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Progression awareness: As the stream nears completion, become more 
    // aggressive about filling existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Penalty for opening a new bin if other options exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
