pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Objective: Minimize post_residual (Best Fit), but penalize small 'slivers' 
    // that are too small for common items, especially as the stream progresses.

    // Penalize small residuals (dead space) quadratically to favor tight fits.
    // The penalty is modulated by progress, becoming more aggressive as the stream ends.
    let sliver_penalty = if post_res < 10.0 {
        (10.0 - post_res).powi(2) * (1.0 + progress)
    } else {
        0.0
    };

    // Reward bins that have residuals close to the next_item_size (Lookahead).
    // This creates a "Best-Fit-Lookahead" effect.
    let lookahead_score = if next_item_size > 0 && post_res >= next_item_size as f64 {
        (post_res - next_item_size as f64).powi(2) * 0.5
    } else if next_item_size > 0 {
        200.0 // Heavy penalty if we can't fit the next item here
    } else {
        0.0
    };

    // If bin_residual == bin_capacity, we are evaluating a NEW bin.
    // We only want to open a new bin if the current open bins are "bad" fits.
    let new_bin_penalty = if bin_residual == bin_capacity {
        // As the stream progresses, the cost of opening a new bin decreases 
        // because we have fewer items left to fill it (avoiding fragmentation).
        15.0 + (open_bins_count as f64 * 0.5) - (progress * 10.0)
    } else {
        0.0
    };

    // Combine factors:
    // Base score is post_res (Best Fit logic).
    // Add penalties for slivers and poor lookahead fit.
    // Add new_bin_penalty to prevent premature new bin opening.
    let score = post_res + sliver_penalty + lookahead_score + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. Lower is better.
    // Logic: Combine Best-Fit (minimizing post_residual) with a penalty for "Dead Space"
    // that cannot accommodate the lookahead item.

    let mut score = post_residual as f64;

    // Harmonic Class Penalty:
    // If the post_residual is too small to fit the next item, we penalize it 
    // unless the post_residual is near zero (meaning we filled the bin perfectly).
    if next_item_size > 0 && post_residual < next_item_size {
