        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 15.0;
        } else {
            score += 50.0; // High barrier to opening a new bin
        }
    }

    // Progression Weighting:
    // As we approach the end of the stream, prioritize closing bins (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    // Harmonic clustering:
    // Favor bins that result in a post_residual that is a multiple of 10,
    // as these leave "cleaner" space for future items.
    if post_residual % 10 != 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
