        score += 25.0 * (1.0 - (post_res / 15.0));
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is too small to fit the next item, add a penalty.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - progress);
    }

    // Heuristic for new bin creation (bin_residual == bin_capacity):
    // Only open a new bin if the current mean_residual is very low (bins are packed tight)
    // or if the stream is nearing completion and we want to consolidate.
    if bin_residual == bin_capacity {
        score += 20.0 + (mean_residual * 0.5) - (progress * 10.0);
    }

    // Avoid opening new bins prematurely if other bins are available
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 40.0 * (1.0 - progress);
    }

    // Discourage filling bins that are already very empty (high residual)
    // relative to the mean_residual of the system.
    if bin_residual > (mean_residual as u32) {
        score += 5.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

