}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post_residuals (Best Fit logic)
    // We want to minimize post_residual to pack tightly.
    let mut score = post;

    // Penalty for empty bins: discouraged unless necessary.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we are early in the stream or if open bins are very full.
        // As the stream progresses, we increase the cost of opening new bins (100.0 is the penalty).
        score += 100.0 * (1.0 - progress.powf(0.5));
    }

    // Lookahead coupling: If a second item is known, penalize bins that leave 
    // too little space for that next item, but reward bins that leave exactly enough.
    if next_item_size > 0 {
        let diff = post - (next_item_size as f64);
        if diff < 0.0 {
            // Cannot fit next item: moderate penalty.
            score += 20.0;
        } else if diff < 10.0 {
            // Highly desirable: leaves minimal waste for the next item.
            score -= 15.0;
        }
    }

    // Efficiency coupling: Use the mean_residual to avoid fragmented bins.
    // If the current bin's residual is significantly better than the mean, prioritize it.
    let residual_improvement = mean_residual - post;
    score -= residual_improvement * 0.5;

    // Last chance logic: If this is the only bin that fits the item, 
    // significantly lower its score to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Non-linear interaction: punish high residual bins more as the stream nears the end.
    score += (post * progress * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
