    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Efficiency: If the current bin is "better" than the average of all open bins, reward it.
    // We prefer to pack into bins that are already "fuller" (lower residual).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 6. Progression Scaling: As we approach the end of the stream, be more aggressive about filling existing space.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual != bin_capacity {
