        if post_residual < next_item_size && post_residual > 0 {
            score += 30.0;
        }
    }

    // 3. Prefer bins that keep the mean residual stable
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 4. Strategic new bin logic:
    // If this is the new bin candidate (residual == capacity), only pick it if 
    // the current fitting bins are very poor matches (high post_residual)
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = -100.0; // Must open new bin
        } else {
            // Only open new if existing bins create very awkward remaining spaces
            score = 150.0; 
        }
    } else {
        // Encourage filling tight gaps
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 5. Progression awareness: tighten constraints as we approach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
