    // 2. Lookahead Synergy: If the next item fits into the current post-residual, 
    // prioritize this bin to reduce fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Dynamic Thresholding: As the stream progresses, become more aggressive 
    // about using existing bins to avoid opening new ones late in the process.
    if is_new_bin {
