        if fitting_bins_count > 0 {
            score += 60.0;
        }
    } else {
        // 4. Global State Awareness: If this bin is significantly below the mean 
        // occupancy, it is a "good" bin. If it's above mean, it's "full".
        // We prefer filling bins that are already relatively full.
        let bin_usage = (bin_capacity - bin_residual) as f64;
        if bin_usage > (bin_capacity as f64 - mean_residual) {
            score -= 10.0;
        }
    }

    // 5. Critical State: If this is the only bin that can fit the item, 
    // we MUST prioritize it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
