    if (bin_residual as f64) > mean_residual * 1.2 {
        score += 15.0;
    }

    // 6. Final adjustment: Prefer bins that maintain a lower total open bin count 
    // by biasing towards bins that have more space consumed.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post_residual (Best Fit principle)
    // We add a non-linear penalty for creating "fragmented" space (small post_residual)
    // that is likely unusable for future items.
    let fragmentation_penalty = if post > 0.0 && post < 15.0 {
        25.0 * (1.0 - (post / 15.0))
    } else {
        0.0
    };

    // Incorporate lookahead: if the next item is large, avoid leaving tiny residuals in the current bin.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 1.5
    } else {
        0.0
    };

    // Dynamically adjust strategy based on progress: 
    // Early in the stream, prioritize tight packing (minimizing post).
    // Late in the stream, accept slightly worse fits to consolidate bins.
    let progress_modifier = 1.0 + (progress * 2.0);

    let mut score = (post * progress_modifier) + fragmentation_penalty + lookahead_penalty;

    // Penalty for opening a new bin (bin_residual == bin_capacity)
    // We increase this penalty as we progress to force consolidation.
    if bin_residual == bin_capacity {
        // Only open a new bin if the fitting_bins_count is 0, or if the best fit is truly abysmal.
        if fitting_bins_count > 0 {
            score += 60.0 + (progress * 40.0);
        } else {
            score -= 10.0; // Minimal incentive to open the first bin
        }
    }

    // Penalize bins that deviate significantly from the mean residual to keep bin levels balanced.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but non-zero (the "fragmentation trap").
    // We target residuals that are smaller than the smallest likely items (10) but not zero.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
