    // 3. Bin Density Balancing: If we have many open bins, penalize opening new ones (bin_residual == capacity).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Exponential penalty for opening a new bin if others are available
            score += 25.0 * (open_bins_count as f64).sqrt();
        }
    }

    // 4. Harmonic Modulo Logic: Favor residuals that align with common item size factors (e.g., 20, 25, 50).
    // This helps maintain "clean" bins for future items.
    let remainder = post_residual % 20;
    if remainder == 0 {
        score -= 5.0;
    } else if remainder > 15 {
        score += 10.0;
    }

    // 5. Last Chance Heuristic: If this is the only bin that fits, prioritize it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Progress Scaling: As the stream nears the end, be more aggressive with packing efficiency.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
