pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize dead space < 10 (unusable)
    // and introduce a pressure mechanism to keep bin count low as the stream progresses.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (gaps < 10 are usually useless given item range 10-100)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If next_item_size fits in the post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Global Bin Pressure: As total_items approach, be more conservative about opening new bins
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        // If we have fitting bins, opening a new one is very expensive
        if fitting_bins_count > 0 {
            score += 100.0 + (progress * 50.0);
        } else {
            // If no bins fit, we must open a new one, normalize score to be competitive
            score = 0.0;
        }
    } else {
        // Favor bins that keep the mean_residual closer to the item_size to maintain balance
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;

        // Penalize fragmentation: higher open_bins_count makes each individual bin's residual more critical
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that cannot fit common items)
    // If post_residual is small but > 0, it's often worse than 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead matching: reward bins where the post_residual can fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0;
        } else {
            // Penalize if we are creating a gap that is too small for the next item
            score += 15.0;
        }
    }

    // 3. Balance usage: if this is a new bin (bin_residual == bin_capacity), 
    // only pick it if the alternative fits are very poor (high post_residual).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Increase cost of new bin to force usage of existing bins
            score += 55.0;
        }
    }

    // 4. Tightness bias: favor bins that bring the residual closer to the global mean
    // This helps maintain a uniform distribution of fill levels across bins.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.2;

    // 5. Urgency: If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progress factor: as we approach the end of the stream, be more aggressive
    // about packing tightly to avoid stragglers.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing (BFD) logic: penalize large residuals to keep bins tightly packed.
    // We already start with post_residual, which favors smaller residuals.

    // 2. Lookahead mechanism: If the next item can fit in the current post_residual, 
    // prioritize this bin to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 * (1.0 - progress);
    }

    // 3. Penalty for opening a new bin unnecessarily.
    // If we have fitting bins, heavily penalize the new bin (bin_residual == bin_capacity).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 120.0;
    }

    // 4. Global state optimization:
    // If the mean residual of current bins is high, we are under-utilizing space.
    // Penalize bins that increase the mean residual further.
    if post_residual as f64 > mean_residual {
        score += 15.0 * (1.0 - progress);
    }

    // 5. Critical Threshold: Avoid creating "dead space" (e.g., < 10) that can't fit 
    // the minimum item size (10), unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 6. Dynamic Scaling: As we approach the end of the stream, 
    // prioritize closing open bins over opening new ones.
    if progress > 0.8 {
        if bin_residual == bin_capacity {
            score += 200.0;
        } else {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9 range) exponentially.
    // Optimal fit is 0 (perfect), but 1-9 is often worse than opening a new bin.
    let gap_penalty = if post_residual > 0 && post_residual < 10 {
        (10.0 - post_res).powf(2.5) * 5.0
    } else {
        0.0
    };

    // Factor in lookahead: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the current choice.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - post_res) * 0.8
    } else {
        0.0
    };

    // Dynamic preference for Best-Fit vs. New-Bin:
    // As progress increases, we become more conservative about opening new bins.
    let new_bin_bias = if bin_residual == bin_capacity {
        // High penalty for opening a new bin early, decreasing as bins fill up.
        (1.0 - progress) * 40.0 + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Coupling post_residual with mean_residual to maintain bin homogeneity.
    // We want to keep residuals close to the mean to avoid "dead" bins.
    let homogeneity_score = (post_res - mean_residual).abs() * 0.2;

    // Final score: Lower is better.
    // We prioritize small post_residual (Best Fit), but add penalties for 
    // unusable gaps and lookahead conflicts.
    post_res + gap_penalty + lookahead_penalty + new_bin_bias + homogeneity_score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large remaining space (standard Best-Fit logic)
    // We favor bins where post_residual is as small as possible.

    // 2. Lookahead Synergy: If next_item_size fits in the post_residual, reward this placement.
    // This is a variation of Next-Fit Decreasing logic applied to the lookahead.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Harmonic Fragmentation Control:
    // If post_residual is small but not zero, it is often "dead space".
    // If post_residual is 0, it's perfect.
    // If post_residual is between 1 and 9, we penalize it heavily as it's unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. New Bin Threshold:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to open a new bin if the best fitting bin is "bad" (i.e., creates high fragmentation).
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is already very low,
        // or if we have very few open bins (early stage).
        if open_bins_count > 0 {
            score += mean_residual * 0.8;
        }
        // Increase cost of opening a new bin as we approach the end of the stream
        score += (step_index as f64 / total_items as f64) * 20.0;
    } else {
        // If this is the only bin that fits, prioritize it heavily to avoid opening a new bin
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 5. Harmonic Class weight:
    // Align with the archetype of preferring bins that leave a remainder that is a multiple of common item sizes.
    score += (post_residual % 10) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual ranges that are 
    // too small to accommodate common small items but large enough to waste space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 20.0;
    }

    // 2. Lookahead Integration: If the next item could potentially fit into the 
    // current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if we have many open bins already.
    // If bin_residual == bin_capacity, we are evaluating the "New Bin" option.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 5.0);
        // Heavily penalize opening a new bin if other bins can still fit the item.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Mean Residual Balancing: Favor bins that stay close to the global average 
    // to keep the packing density uniform across all active bins.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.5;

    // 5. Progression Scaling: As the stream nears the end, be more aggressive 
    // about filling existing bins to avoid leftover items forcing new bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals.
    // The base score is already post_residual, which favors tight fits.

    // 2. Lookahead Synergy: If the post_residual can perfectly or nearly accommodate the next item, 
    // significantly reduce the score to prioritize this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that leave exactly enough or very close to enough space for the next item.
            let waste_after_next = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 / (1.0 + waste_after_next));
        } else {
            // Penalize bins that leave a gap too small for the next item, 
            // especially if that gap is "trapped" (between 1 and 9, since min item size is 10).
            if post_residual < 10 {
                score += 25.0;
            }
        }
    }

    // 3. New Bin Thresholding: Prevent opening a new bin unless the existing fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the average residual of current bins is already quite high,
        // or if we have very few bins open (to avoid fragmentation).
        if open_bins_count > 0 && mean_residual < 25.0 {
            score += 60.0;
        } else {
            score += 10.0;
        }
    }

    // 4. Fitting Pressure: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // 5. Progression Weighting: As the stream nears the end, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin && progress > 0.8 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
