    // it's often unusable for future items (e.g., < 10).
    if post_res > 0.0 && post_res < 10.0 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead coupling: if the next item is large, penalize bins that cannot fit it
    // after this placement.
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
