        // Also penalize opening a new bin if an existing bin could take the item
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Global balance: penalize bins that deviate significantly from the mean_residual
    // to encourage uniform fill across open bins.
    let deviation = (post_res - mean_residual).abs();
    score += 0.5 * deviation * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

