    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalize opening a new bin heavily unless the current open bins are highly fragmented
        // or we are near the end of the stream where we don't care about packing tight.
        let progress = step_index as f64 / total_items as f64;
        score += 25.0 + (mean_residual * 0.5) - (progress * 10.0);
    } else {
        // Penalty for creating 'dead space' (bins that can't fit most future items)
