            score += 40.0;
        }

        // Harmonic class logic: favor residuals that align with common item sizes
        // or prioritize filling bins that are already "half-empty" to keep others empty.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score += (fill_ratio * 10.0);

        // If this is the only bin that fits, prioritize it strongly
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
