}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res_f = post_residual as f64;

    // Penalize small residuals that are too small for common items (dead space)
    // We create a non-linear "valley" for post_residual.
    let dead_space_penalty = (10.0 - post_res_f).max(0.0).powi(2) * 5.0;

    // Lookahead logic: if next_item_size is large, avoid creating a bin that can't fit it.
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size - post_residual) as f64 * 1.5
    } else {
        0.0
    };

    // Global strategy: As we approach the end of the stream, prioritize tightly packed bins.
    // Early in the stream, be more conservative about opening new bins.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (50.0 * (1.0 - progress)) + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Interaction between mean_residual and current state to encourage bin consolidation.
    let consolidation_bonus = if !is_new_bin {
        (post_res_f - mean_residual).abs() * 0.2
    } else {
        0.0
    };

    // Base score is the post_residual itself, balanced by the non-linear penalties.
    // Lower score is better.
    post_res_f + dead_space_penalty + lookahead_penalty + new_bin_penalty + consolidation_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that cannot fit future items (Small item threshold)
    // If post_residual is small but > 0, it's often a waste unless it fits the next item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Class Logic: Reward placements that result in "good" residuals
    // We favor residuals that are multiples of 25 or near 0, as they maximize packability.
    let harmonic_penalty = (post_residual % 25) as f64 * 0.8;
    score += harmonic_penalty;

    // 3. Lookahead Logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. New Bin Thresholding: 
    // If bin_residual == bin_capacity, we are evaluating a brand new bin.
    // We only open a new bin if the existing options are very poor (high post_residual).
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of current bins is already quite low,
        // or if we have very few bins open (to avoid fragmentation).
        score = 35.0 + (mean_residual * 0.5);
    } else {
        // If this is the last chance for the current item, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 5. Progression awareness: As we near the end of the stream, tighten constraints.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual while penalizing "dead zones" (gaps < 10) 
    // and balancing against the cost of opening new bins.

    let mut score = post_residual as f64;

    // 1. Penalize dead space (gaps too small to fit the smallest possible item: 10)
    // If the post_residual is in the range [1, 9], it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead optimization: If next_item_size is known, penalize placements 
    // that make it impossible to fit the next item in the same bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Pressure against opening too many bins: 
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless there are no other viable options (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If it's the only choice, reset score to base
            score = 1.0;
        }
    }

    // 4. Prefer bins that keep the mean_residual high (to accommodate future large items)
    // We add a small factor based on the difference between this bin's post_residual 
    // and the global mean.
    score += (mean_residual - post_residual as f64) * 0.5;

    // 5. Dynamic scaling based on stream progression
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + (progress * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We prioritize bins that result in smaller residuals.

    // 2. Lookahead Synergy (The "Perfect Match" Bonus):
    // If post_residual is close to next_item_size, reward this bin heavily.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;

