        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        }
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless
    // existing bins are highly fragmented or no good fits exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
