            // Neutralize score for necessary new bin creation
            score = 50.0;
        }
    }

    // 4. Fragmentation Control:
    // Penalize bins where the post_residual is small but unusable (e.g., < 10)
    // unless it is exactly 0 (a perfect fill).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 5. Global Density Balancing:
    // Favor bins that align with the current average residual to keep
    // the distribution of bin usage uniform.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.1;

    score
