        score = 85.0 + (open_bins_count as f64 * 0.5) + (progress * 20.0);
    } else {
        // Reward tight fits (Best Fit principle).
        // post_residual is already part of the score; smaller is better.

        // Lookahead adjustment: If the next item can fit in the remaining post_residual, 
        // we heavily favor this bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }

        // Penalize bins that would be left with a 'dead zone' (e.g., < 10 space left)
        // unless it's a perfect fit (post_residual == 0).
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }

        // Balance against global state: if we have many open bins, prioritize 
        // filling the ones that are already quite full (lower mean_residual).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }

        // If this is the only bin that can fit the item, we must take it.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;

    // Penalize small residuals (dead space) especially as the stream nears the end
    // to encourage tighter packing early on.
    let dead_space_penalty = if post < 10.0 {
        (10.0 - post) * (1.0 + progress * 5.0)
    } else {
        0.0
    };

    // Factor in lookahead: if next_item_size is large, prefer leaving space (higher post_residual)
    // If next_item_size is small, prioritize filling the current bin (lower post_residual)
    let lookahead_factor = if next_item_size > 0 {
        let diff = (next_item_size as f64) - post;
        if diff > 0.0 {
            // Next item doesn't fit well, penalize this bin
            diff * 0.5
        } else {
            // Next item fits well, reward this bin
            diff.abs() * -0.3
        }
    } else {
        0.0
    };

    // Normalize open_bins_count impact to prevent excessive bin proliferation
    let open_bins_pressure = (open_bins_count as f64).powf(1.2) * (1.0 - progress * 0.5);

    // If bin is empty, apply a base cost that scales with total progress
    // This forces the algorithm to be more conservative about opening new bins later in the stream.
    let empty_bin_penalty = if bin_residual == bin_capacity {
        25.0 + (progress * 50.0)
    } else {
        0.0
    };

    // Combine factors
    // Lower score is better.
    post + dead_space_penalty + lookahead_factor + open_bins_pressure + empty_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
