    // We want the post_residual to be as close to 0 as possible.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Lookahead: If the next item is large, avoid leaving a residual that is "useless".
    // If post_residual is smaller than the next item, we create dead space.
    if next_item_size > 0 {
