    // If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Global state awareness: if we are nearing the end of the stream, 
    // be more aggressive about filling existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // New-bin thresholding:
    // If the current bin is empty (bin_residual == bin_capacity), 
    // penalize opening a new bin unless existing bins are very full.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already very low,
        // or if we have no other choice.
        if mean_residual > 15.0 && open_bins_count > 0 {
            score += 50.0;
        } else {
            score += 25.0;
        }
    }

    // Fitting density: if this is the only bin that fits the current item, 
    // prioritize it heavily to avoid unnecessary new-bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Adaptive weighting based on how full the bin will be relative to the mean:
    // Favor bins that end up closer to the mean residual of the system.
    let target_residual = (bin_capacity as f64 - mean_residual).min(20.0);
    score += (post_residual as f64 - target_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space; lower is better (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: non-linear growth as the stream progresses.
    // We want to be more conservative about opening new bins late in the stream.
    if is_new_bin {
        score += 25.0 + (progress * 50.0).powf(1.5);
    } else {
        // Penalty for leaving a "sliver" (fragmentation) that is hard to fill.
        // A residual between 1 and 9 is often unusable for items >= 10.
        if post_residual > 0 && post_residual < 10 {
            score += 40.0 * (1.0 - progress);
        }

        // Lookahead heuristic: if the next item is large, avoid bins that leave 
        // insufficient space for it.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Encourage packing into bins that are already "tight" to maximize density.
    // Lower mean_residual means we have bins with less space, so we prefer to 
    // fill those rather than creating new bins.
    score += (mean_residual - post_residual as f64) * 0.2;

    // If this is the only bin that fits, prioritize it heavily to avoid opening a new one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

