        }
    }

    // 5. Global density balancing: If open bins are accumulating, penalize opening new ones.
    let density_penalty = (open_bins_count as f64) * 2.0;
    score += density_penalty;

    // 6. Mean-residual alignment: Penalize bins that deviate significantly from the mean,
    // encouraging a uniform "filling level" across the set of active bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
