        // Encourage filling bins that are already closer to the mean residual to keep bin usage balanced.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 2.0;

        // If this is the only bin that can fit the item, heavily prioritize it.
        if fitting_bins_count == 1 {
            score -= 1000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large remaining gaps (avoid fragmentation)
    // We favor smaller post_residuals (the tighter the fit, the better)
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic:
    // If the post_residual is a multiple of common item sizes, it is more likely to be filled later.
    // We reward post_residuals that are close to the next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;
    }

    // 3. Thresholding/New Bin logic:
    // If this is an empty bin (new bin request), add a constant penalty to discourage opening
    // unless the fit in existing bins is extremely poor.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is dynamic based on how many bins are already open.
        // If many bins are open, opening a new one is more expensive.
        score += 25.0 + (open_bins_count as f64 * 2.0);
    } else {
        // If this bin is the last chance for the current item, prioritize it heavily
        // to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 4. Mean Residual Coupling:
    // Avoid bins that deviate significantly from the average empty space in other bins
    // to keep the bin distribution uniform.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 5. Progression scaling:
    // As the stream nears the end, be more aggressive about packing tightly.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (e.g., < 10), it is likely unusable.
    // We penalize values in the (0, 10) range heavily to encourage tighter fits or new bins.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Open Bins Pressure: Penalize opening new bins when current ones are available.
    // If this is a new bin (bin_residual == bin_capacity) and we have existing bins,
    // apply a significant penalty to force the algorithm to prefer existing bins.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 60.0 + (open_bins_count as f64 * 2.5);
    }

    // 3. Lookahead Sensitivity: If the next item is large, avoid leaving small residuals
    // that won't fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 25.0;
        }
    }

    // 4. Mean Residual Balancing: Favor bins that keep the mean residual closer to 
    // the optimal packing density (approx 20-30% of capacity).
    let deviation = (post_residual as f64 - (bin_capacity as f64 * 0.25)).abs();
    score += deviation * 0.1;

    // 5. Fitting Constraint: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

