    // Global state awareness: if we are running out of items, be more aggressive with packing
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // Heuristic for new bin allocation
    if is_new_bin {
        // Only open a new bin if the current 'best' fit is actually quite poor (high residual)
        // or if we have very few open bins and want to preserve space for larger future items
        if fitting_bins_count > 0 {
            score += 60.0 + (mean_residual * 0.5);
        } else {
            score -= 10.0;
        }
    } else {
        // Prefer bins that are already partially filled (lower mean_residual)
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Final tie-breaker: prefer tighter fits
    score += (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // 1. Base Score: Penalize larger post_residuals (Best Fit logic)
    // We emphasize minimizing the remaining space to pack tightly.
    let mut score = post;

    // 2. Lookahead Coupling: If next_item_size is large, penalize small post_residuals
    // that would strand the next item. If next_item_size is 0, ignore.
    if next_item_size > 0 {
        let penalty = if post < next_item_size as f64 {
            (next_item_size as f64 - post).powf(1.5)
        } else {
            0.0
        };
        score += penalty * (1.0 - progress * 0.5);
    }

    // 3. Dynamic New-Bin Thresholding:
    // When bin_residual == bin_capacity, we are evaluating a "New Bin".
    // We make it expensive early on, but cheaper as the stream progresses 
    // to avoid leaving too many bins partially filled at the end.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high (capacity/2)
        // We reduce this cost as we approach the end of the stream.
        score = (capacity * 0.5) * (1.1 - progress);
    } else {
        // 4. Density Balancing:
        // Penalize bins that deviate significantly from the mean_residual
        // to encourage uniform fill levels across all active bins.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.25;
    }

    // 5. Urgency Calibration:
    // If this is the only bin that can fit the item, prioritize it strongly
    // to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= (capacity * 0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

