    // We prioritize bins where the remaining space is small, reducing fragmentation.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Reward placements that result in "tight" remainders
    // that are likely to be filled by common item sizes (e.g., 20, 25, 33, 50).
    if post_residual > 0 && post_residual < 20 {
        score -= 15.0; // Reward tight fits (near-perfect packing)
    }

