            // Strong penalty for opening a new bin if we have existing capacity
            score += 65.0 + (30.0 * (1.0 - progress));
        } else {
            // No choice, must open
            score = 0.0;
        }
    }

    // 4. Global state coupling: Encourage filling bins that are already "half-full"
    // based on the mean_residual of open bins.
    let current_bin_usage = bin_capacity - bin_residual;
    let mean_usage = bin_capacity as f64 - mean_residual;
    if current_bin_usage < mean_usage as u32 {
        score += 5.0;
    }

    // 5. Final constraint: If this is the last chance to fit an item (fitting_bins_count == 1),
    // be slightly more lenient to avoid unnecessary new bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily as the stream progresses, 
    // unless the current bin is nearly empty (avoiding early fragmentation).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 
        25.0 + (progress * 50.0) 
    } else { 
        0.0 
    };

    // Best-Fit Decreasing logic: favor small post_residuals (tight packing)
    // but apply a non-linear penalty for "stranded" small residuals (e.g., 1-9)
    // which are statistically hard to fill later.
    let stranded_penalty = if post < 10.0 && post > 0.0 {
        15.0 * (1.0 - post / 10.0)
    } else {
        0.0
    };

    // Lookahead interaction: If the next item is large, prioritize bins that keep 
    // enough space to accommodate it.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        20.0 * (1.0 - (post / next_item_size as f64))
    } else {
        0.0
    };

    // Global efficiency: If we have many open bins, penalize the creation of 
    // even more by increasing the cost of new bins proportionally to open_bins_count.
    let density_penalty = if is_new_bin {
        open_bins_count as f64 * 2.0
    } else {
        0.0
    };

    // Combine terms: 
    // Base score is the residual (lower is better), modified by penalties.
    post + new_bin_penalty + stranded_penalty + lookahead_penalty + density_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that cannot fit common items)
    // We prioritize keeping the residual either 0 or large enough to fit the next item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Harmonic class alignment: Prefer filling bins to specific thresholds
    // Bins with residuals near 25, 50, or 75 are often more flexible for future items
    let target_residuals = [25.0, 50.0, 75.0];
    for &target in &target_residuals {
        let diff = (post_residual as f64 - target).abs();
        score += diff * 0.1;
    }

    // 4. If this is the only bin that fits the item, avoid opening a new one unless the residual is very poor
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. New Bin Logic: Discourage opening a new bin unless the current available bins are all poor fits
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Only open a new bin if the average residual of existing bins is already tight
            if mean_residual > 20.0 {
                score += 10.0;
            } else {
                score += 100.0;
            }
        }
    }

    // 6. Progression scaling: As we approach the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit future items.
    // If the residual is less than the smallest possible item (assumed ~10), it is "wasted".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Coupling: If next_item_size is known, heavily penalize bins that 
    // cannot accommodate the next item when they could have if chosen differently.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // scaled by the number of currently open bins to force consolidation.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.5);
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, 
    // reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Efficiency: If the current bin's post_residual is significantly 
    // better than the mean_residual of other bins, prioritize it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Lookahead logic: Reward bins that can perfectly fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit or near-perfect fit reward
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 / (1.0 + diff)) * 2.5;
        } else {
            // Penalty for stranding an item that could have fit
            score += 15.0;
        }
    }

    // 3. Last-Chance logic: If this is the only bin that can fit, take it to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. New-Bin logic: Penalize opening a new bin heavily unless necessary
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0;
        }
    }

    // 5. Mean residual balancing: Keep bin packings dense relative to the average
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 6. Progressive packing: Tighten constraints as we reach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

