    // 2. Lookahead Integration: If next_item_size is large, favor larger post_residuals
    //    that might accommodate it, but only if we aren't near the end of the stream.
    if next_item_size > 0 {
        let fit_next = post_residual >= next_item_size;
        if fit_next {
            // Reward bins that can accommodate the next item by reducing the cost
            score -= (next_item_size as f64) * 0.8;
        } else {
            // Penalize bins that would be too small for the next item if we are mid-stream
            score += (1.0 - progress) * (next_item_size as f64) * 0.4;
        }
    }

    // 3. Global State: If we have many open bins, prioritize tightening the most empty ones
    //    to keep the count of open bins low.
    if open_bins_count > 5 {
        score += (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless fitting_bins_count is low or the current item is very large.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0; // Forced to open
        } else {
            // Only open a new bin if the current fit is extremely inefficient
            score += 45.0 + (item_size as f64 * 0.5);
        }
    }

    // 5. Residual Balancing: Prevent fragmentation by penalizing residuals 
    //    that are too small to fit common items (< 15).
    if post_residual > 0 && post_residual < 15 {
        score += 20.0 * (1.0 - (post_residual as f64 / 15.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
