    // but becomes necessary if fitting bins are scarce.
    if is_new_bin {
        // Base cost of new bin is high to discourage premature opening
        score += 45.0; 
        // Dynamic adjustment: Penalize new bins more if we are early in the stream 
        // to encourage packing into existing bins.
        score += (1.0 - progress) * 30.0;
        // If we have many fitting bins, opening a new one is highly suboptimal
        score += (fitting_bins_count as f64).powf(1.5) * 5.0;
    } else {
        // For existing bins:
        // 1. Penalize creating "dead zones" (small residuals) that are unlikely to fit future items.
        // If post_residual is very small (1-9), it is often worse than a slightly larger one.
        if post_residual < 10 {
            score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
        }

        // 2. Lookahead coupling: If next_item_size is large and fits in current post_residual, 
        // reward this bin. If it doesn't fit, add a slight penalty.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
