            }
        }
    }

    // 3. Global constraint: If only one bin fits, prioritize it heavily to avoid opening a new one.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 20.0;
    }

    // 4. Smooth coupling with mean_residual to maintain bin density balance.
    // If this bin's residual is significantly better than the mean, favor it.
    score += (post_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
