    // 3. Lookahead Matching: Reward bins that become perfect fits for the next item
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs();
        if diff == 0 {
            score -= 20.0; // Strong reward for perfect next-fit
        } else if diff < 10 {
            score -= 10.0; // Moderate reward for near-fit
        }
    }

    // 4. Mean Residual Balancing: Avoid creating bins that deviate significantly from average
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Urgency: If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 6. Progression Scaling: Be more conservative with new bins as the stream nears completion
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 15.0; 
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that likely won't fit future items)
    // If post_residual is < 10, it is likely unusable given the item range (10-100).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If the next item fits into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global state awareness: If we are near the end of the stream, prioritize filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 4. Heuristic: If this is the only bin that fits, we must take it (unless it's an empty bin).
    // The empty bin case has bin_residual == bin_capacity.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Balance bin usage: Avoid opening new bins unless the fit is excellent.
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin; only do it if the item is large or no other good options.
        score += 45.0;
        if item_size > 70 {
            score -= 20.0;
        }
    }

    // 6. Prefer bins that are already "tight" to keep open bins consolidated.
    // We compare post_residual to the mean_residual of all open bins.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalty for creating a "sliver" (small unusable space)
    // We penalize values of post_residual that are small but > 0.
    // Optimal is either 0 (perfect fit) or large enough to fit future items.
    let sliver_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post) * 2.5
    } else {
        0.0
    };

    // Coupling: Use lookahead to penalize closing a bin that could have accommodated the next item
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 1.2
    } else {
        0.0
    };

    // Encourage filling bins early in the stream (low progress)
    // Discourage opening new bins as the stream progresses
    let open_new_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 0.5) + (progress * 20.0)
    } else {
        0.0
    };

    // Favor bins that align with the global average residual
    let deviation_penalty = (post - mean_residual).abs() * 0.1;

    // Base score: prioritize smaller post_residual (Best Fit logic)
    // Modified by non-linear penalties
    let score = post + sliver_penalty + lookahead_penalty + open_new_bin_penalty + deviation_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (fragmentation)
    // We favor bins that become very tight (Best-Fit principle).
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Lookahead: If next_item can fit in this post_residual, 
    // prioritize this bin heavily to prevent opening new ones later.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Last-Chance Logic: If this is the only bin that fits the current item, 
    // we must take it regardless of fit quality.
    if fitting_bins_count == 1 && bin_residual >= item_size {
