    }

    // 4. Empty Bin Threshold: Penalize opening a new bin unless the current 
    // open bins are already very full (high mean_residual).
    if bin_residual == bin_capacity {
        // Only open a new bin if the average space in current bins is already quite small.
        // This encourages packing current bins tighter before starting a new one.
        score += (100.0 - mean_residual) * 2.0;

        // Dynamic scaling based on stream progression: as we near the end, 
        // be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 50.0;
    }

    // 5. Harmonic "Tightness" Reward:
    // If post_residual is small (e.g., < 10), it is highly desirable (near-perfect fit).
    if post_residual < 10 {
        score -= 50.0;
    }

    // 6. Modulo-based fragmentation penalty:
    // Avoid creating "dead" residuals that are unlikely to fit common item sizes.
    // Penalize residuals that fall in the "unlucky" range (e.g., 1-9).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
