    }

    // Global density balancing:
    // Penalize placements that deviate significantly from the current mean residual
    // to keep bins balanced and prevent "bin starvation".
    let dev = (post_res - mean_residual).abs();
    score += dev * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
