pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the remaining space is too small to fit the smallest expected items (10),
    // it becomes "toxic" dead space. We penalize post_residual values in the range (0, 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead optimization: If the next item exists, penalize bins that cannot fit it
    // after placing the current item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open bins pressure: Discourage opening new bins (bin_residual == bin_capacity).
    // If we are forced to open a new bin, we apply a base cost unless the open_bins_count is low.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting constraints: If this is the only bin that can fit the item, prioritize it
    // heavily to avoid premature new bin allocation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global efficiency: Favor bins that stay closer to the mean residual of existing bins
    // to keep the packing uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 6. Progress scaling: As we approach the end of the stream, prioritize tight fits
    // more aggressively to minimize trailing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": residuals below 10 are often impossible to fill.
    // We penalize the range [1, 9] heavily to encourage perfect fits.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: If the next item fits perfectly into the current post_residual,
    // we prioritize this bin heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Reward bins that leave enough space for the next item
            score -= 10.0;
        }
    }

    // If this is the only bin that can fit the item, we must prioritize it
    // unless the post_residual is extremely poor.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global optimization: If we are near the end of the stream, prioritize 
    // filling bins as tightly as possible to reduce total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    // New bin logic: If bin_residual == bin_capacity, this is the "New Bin" candidate.
    // We only open a new bin if the current best score for existing bins is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = 35.0;

        // If we have many open bins already, we become more reluctant to open another.
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: favor smaller post_residuals (the baseline).
    // 2. Penalty for creating "dead space": If post_residual is < 10, it's often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead optimization: If next_item_size fits in the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Global state awareness: If we are late in the stream, be more aggressive about filling bins.
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // 5. New Bin Logic: Discourage opening a new bin unless the existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin is high.
        // It only becomes viable if existing bins are very full (low mean_residual).
        score += 35.0 + (mean_residual * 0.5);
    } else {
        // Encourage using existing bins that have a residual close to the average.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 6. Scarcity heuristic: If only one bin can fit this item, prioritize it to prevent 
    // forcing a new bin later for a potentially larger item.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals that are too small for common future items (the "fragmentation trap")
    // If post_residual is < 10, it's likely dead space. 
    let fragmentation_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Reward bins that keep the mean_residual high (avoids packing bins too tightly early on)
    // As progress approaches 1.0, we become more aggressive about filling bins (Best Fit behavior)
    let tightness_factor = (mean_residual - post) * (1.0 - progress);

    // Lookahead logic: if next_item_size fits in the post_residual, prioritize this bin
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        -15.0 * (1.0 + progress)
    } else {
        0.0
    };

    // New bin penalty: discourage opening a new bin unless the existing fit is extremely poor
    // We scale this penalty by the number of open bins to encourage consolidation
    let new_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 2.5) + (progress * 20.0)
    } else {
        0.0
    };

    // Non-linear coupling: square the post_residual to penalize "medium" fits 
    // that leave awkward gaps, while favoring tight fits.
    let base_score = post.powf(1.2);

    base_score + fragmentation_penalty + tightness_factor + lookahead_bonus + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post-residuals to keep bins tightly packed.
    // We emphasize small post_residuals (near 0) as ideal.
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: Reward placements that leave a residual which is a multiple 
    // of common item sizes, or conversely, penalize 'dead zones' that cannot fit typical items.
    // If post_residual is < 10, it is likely wasted space (since items are >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 3. Lookahead Sensitivity: If next_item_size is large, favor bins that can accommodate it.
    // If next_item_size exists and current bin cannot fit it after current placement, penalize.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. New Bin Thresholding: Discourage opening a new bin unless the current fit is catastrophic.
    // If bin_residual == bin_capacity, we are evaluating the cost of a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of existing bins is already very low (fragmented).
        if mean_residual > 20.0 {
            score -= 25.0;
        } else {
            score += 50.0;
        }
    }

    // 5. Fitting Density: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progressive Tightening: As we reach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "orphaned" gaps
    // that cannot fit subsequent items, while scaling cost by open bin density.

    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is too small to fit the smallest
    // possible items (assuming 10 as lower bound) or the next known item,
    // we penalize it to discourage creating unusable fragments.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Integration: If the next item cannot fit in the current post_residual,
    // we apply a penalty to prioritize bins that can accommodate the sequence.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Density Management: If fitting_bins_count is 1, we are at a "choke point".
    // We heavily incentivize using the last fitting bin to avoid opening new ones.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 4. Global Pressure: As the stream progresses, favor bins that keep the 
    // mean_residual high (balanced utilization) to prevent fragmented bins.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64 * 2.0) * (1.0 - progress);

    // 5. New Bin Threshold: Discourage opening a new bin unless the current 
    // fit is extremely poor (post_residual < 5).
    if bin_residual == bin_capacity {
        if post_residual > 90 {
            score -= 10.0; // Accept new bin if it's a perfect fit for a large item
        } else {
            score += 60.0; // High penalty for opening new bins unnecessarily
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep space tight.
    // The base score is already post_residual. We refine it.

    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward this placement.
    // This creates a "perfect fit" potential for the next step.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;
    }

    // 3. New Bin Thresholding: Penalize opening a new bin unless the fit is extremely poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only consider a new bin if we have very few options or the items are large.
        // We add a high cost to new bins, but reduce it if the current fitting options are scarce.
        score += 40.0 - (fitting_bins_count as f64 * 5.0);
    } else {
        // 4. Mean Residual Balancing: Penalize bins that deviate significantly from the mean.
        // We want to keep all bins filled at similar levels to prevent "fragmentation".
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 5. Urgency factor: As we approach the end of the stream, prioritize packing density.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.1);

    // 6. Hard constraint: If a bin is the ONLY one that fits, give it a massive priority boost.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. 
    // We prioritize Best-Fit (minimizing post_residual) but penalize "fragmentation" 
    // where post_residual is too small to accommodate common subsequent items.

    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (e.g., residual < 10) unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin heavily to increase packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Global state: If we are late in the stream, favor bins that are already open
    // to avoid inflating the total bin count (Best-Fit Decreasing intuition).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with progress.
        // Opening a new bin early is fine, but late in the stream is costly.
        score += 20.0 + (progress * 50.0);
    }

    // 4. If this is the last chance for the current item (fitting_bins_count == 1),
    // we should prioritize using it unless the fit is extremely poor (post_residual is large).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Balance residuals: If this bin's residual is significantly lower than the mean,
    // it's a "tight" bin. We prefer filling tight bins to keep "loose" bins available.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space after placement. 
    // We want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating a "sliver" (fragmentation):
    // If post_residual is small but > 0, it's likely unusable for future items (min size 10).
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic:
    // If next_item_size fits in the current post_residual, reward this bin.
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= (next_item_size as f64) * 0.8;
    }

    // Dynamic thresholding based on stream progress:
    // As we reach the end of the stream, we become more aggressive in packing tightly (Best Fit).
    // Early in the stream, we allow slightly more open bins to maintain flexibility.
    let flexibility_bias = (1.0 - progress) * (open_bins_count as f64) * 2.0;
    score += flexibility_bias;

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy cost unless
    // no other bins can fit the item or the remaining space is extremely tight.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0 + (mean_residual * 0.5);
        } else {
            // If no other bin fits, this is mandatory.
            score -= 10.0;
        }
    }

    // Non-linear interaction: discourage bins that deviate significantly from the mean_residual
    // to keep the bin distribution uniform.
    let residual_deviation = (post - mean_residual).abs();
    score += residual_deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the post_residual (Best Fit logic).
    let mut score = post_residual as f64;

    // 1. Harmonic Class Penalty: Penalize residuals that are small but unusable (1-9).
    // This pushes items into bins where the remaining space is more likely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Coupling: If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than the next item, we penalize the bin heavily.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward bins that leave exactly enough space for the next item (perfect fit).
            score -= (post_residual - next_item_size) as f64 * 0.1;
        }
    }

    // 3. Fragmentation Control: If this is the only bin that fits, we are forced to take it.
    // However, if we have multiple options, we penalize the "New Bin" (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is already very tight.
        // If mean_residual is high (lots of space), opening a new bin is wasteful.
        score += 20.0 + (mean_residual * 0.5);
    }

    // 4. Density Balancing: Favor filling bins to high capacity early.
    // Use modular arithmetic to favor "clean" cuts (e.g., leaving 0, 20, or 25 space).
    let rem_mod = post_residual % 20;
    if rem_mod == 0 {
        score -= 5.0;
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive 
    // about fitting items into existing bins to minimize total bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the remaining space (Best Fit variant)
    let mut score = post_residual as f64;

    // Penalty for creating 'unusable' slivers (1..9) which are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if next item is large and current post_residual is too small, penalize
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Pressure to consolidate: penalize opening new bins as the stream progresses
    if bin_residual == bin_capacity {
        // Higher penalty for new bins based on how many bins are already open
        score += 40.0 + (open_bins_count as f64 * 2.0) + (progress * 20.0);
    } else {
        // Reward filling bins that are already "tight" compared to the mean
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }

        // If this is the only bin that can fit the item, prioritize it to avoid new bin creation
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Favor keeping residuals balanced across open bins
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // We heavily penalize the "New Bin" (bin_residual == bin_capacity) to prevent 
    // premature opening unless necessary.
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 2. Lookahead Synergy: If the post_residual can accommodate the next item, 
    // reward this bin to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Fragmentation Avoidance: Penalize residuals that are too small to fit 
    // common small items but too large to be considered "tight".
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. Mean Residual Balancing: If this bin's residual is significantly 
    // better than the average, reward it to keep the global variance low.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // 5. Last-Chance Logic: If this is the only bin that can fit the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progress Weighting: As the stream nears completion, become more 
    // conservative with opening new bins by increasing the cost of empty bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is "too empty" (under 20% full)
    if post_residual > 80 {
        score += 50.0;
    }

    // Best-Fit Decreasing logic: heavily penalize leaving a tiny residual (1-9)
    // as it is unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: If next item exists, reward bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            // Penalize if current placement forces a new bin for the next item
            score += 15.0;
        }
    }

    // Global state awareness: If we have many open bins, prioritize tightening existing ones.
    // If open_bins_count is high, we want to minimize post_residual strictly.
    score += (open_bins_count as f64) * 2.0;

    // Dynamic threshold: As we approach the end of the stream, prioritize minimizing 
    // total bins used by being more aggressive in filling bins (lower post_residual).
    score += (progress * 20.0);

    // If this is the only bin that fits the current item, prioritize it to avoid
    // the penalty of opening a brand-new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Special handling for the "New Bin" candidate (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have too many open bins already that are mostly empty,
        // or if we are forced to (fitting_bins_count == 0).
        if fitting_bins_count > 0 {
            score += 45.0 + (mean_residual * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement.
    // Minimizing this favors Best-Fit behavior.
    let mut score = post_res;

    // Penalty for creating 'dead space' that is too small to fit typical future items.
    // We use a non-linear quadratic penalty for small residuals (0 < post_res < 10).
    if post_res < 10.0 {
        score += (10.0 - post_res).powi(2) * 5.0;
    }

    // Lookahead logic: if next_item_size is known, penalize residuals that are 
    // too small to accommodate the next item.
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            score += 25.0 * (1.0 + progress);
        }
