    }

    // If this is the only bin that can fit the item, give it a significant priority boost
    // by subtracting from the score.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Balance open bins: penalize creating a new bin if we have many under-utilized bins.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += (open_bins_count as f64) * (1.0 - progress) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (wasted space)
    // 2. Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 3. Lookahead synergy: if next_item_size fits in post_residual, prioritize this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 4. Harmonic thresholding: penalize residuals that leave awkward gaps (e.g., < 10)
    // Small gaps often become "dead" space that no future item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 5. Adaptive pressure: as the stream progresses, become more aggressive in 
    // filling existing bins to reduce the open_bins_count.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    // 6. Near-full bin optimization: prioritize bins that are near capacity
    // to "close out" a bin (leaving very little residual).
    if post_residual < 5 {
        score -= 15.0;
    }

    // 7. Avoid fragmentation: if only one bin can fit the item, we are forced to pick it.
    // We adjust the score to ensure we don't prefer a new bin over a valid fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

