    // 2. Lookahead: If the next item can fit perfectly or near-perfectly into the post_residual, prioritize this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that create a "perfect" or "near-perfect" fit for the next item
            let gap = (post_residual - next_item_size) as f64;
            score -= (100.0 - gap) * 0.5;
        } else {
