            score += 20.0;
        }
    }

    // 3. Fragmentation control: If this is the last fitting bin, avoid opening a new bin unless necessary.
    // We heavily penalize opening a new bin (where bin_residual == bin_capacity) unless the mean_residual is very low.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && fitting_bins_count > 0 {
