            score += 150.0 + (mean_residual * 2.0);
        } else {
            // Allow opening new bin if no other options exist
            score -= 50.0;
        }
    }

    // 4. Tightness bias: Favor bins that are already "tight" (low residual)
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // 5. Progression scaling: As we near the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Penalize small residuals (Best-Fit principle)
    // We want to minimize the post_residual, but avoid creating "slivers" (very small unusable gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead logic
    // If we have a next item, penalize bins that cannot fit it after this placement
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 35.0;
        } else {
            // Reward bins that can accommodate the next item perfectly
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // 3. Global state management
    // If a bin is the only one that can fit the item, prioritize it strongly
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // 4. Dynamic New-Bin Threshold
    // As the stream progresses, become increasingly conservative about opening new bins
    if is_new_bin {
        // Base cost for opening a new bin
        score += 25.0;
        // As we reach the end of the stream, increase penalty to force consolidation
        score += 60.0 * progress;
        // If many bins are already open, penalize opening another
        score += (open_bins_count as f64) * 2.0;
    } else {
        // Encourage balanced fill across existing bins
        score += (post_residual as f64 - mean_residual).abs() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize tightest fit (Best Fit logic)
    let mut score = post;

    // Penalty for creating a bin that is too empty (near-empty bin avoidance)
    // As progress increases, we become more aggressive about filling bins (less tolerance for high post_residual)
    let emptiness_penalty = (post * post / bin_capacity as f64) * (1.0 + progress);
    score += emptiness_penalty;

    // Lookahead logic: If the next item is large, prioritize keeping larger residuals open.
    // If the next item is small, prioritize finishing off bins.
    if next_item_size > 0 {
        let lookahead_impact = (next_item_size as f64 - post) * (1.0 - progress);
        score += lookahead_impact;
    }

    // Heuristic for new bin creation:
    // Only open a new bin if the current fit is extremely poor (large post_residual)
    // or if we are nearing the end of the stream and have many open bins.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless the existing fitting bins are very poor
        // Scaling with open_bins_count to discourage fragmentation
        score = 45.0 + (open_bins_count as f64 * 2.5) - (progress * 10.0);
    } else {
        // Penalize the "last chance" scenario if it results in a very small residual
        if fitting_bins_count == 1 && post < 10.0 {
            score -= 5.0;
        }
    }

    // Adjust for global efficiency: align towards the mean residual to keep bins balanced
    let balance_factor = (post - mean_residual).abs() * 0.1;
    score += balance_factor;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

