        }
    }

    // 4. Harmonic/Modulo pressure:
    // Penalize residuals that are not multiples of common item sizes (e.g., 20, 25)
    // to keep space usable for future items.
    if post_residual % 20 != 0 {
        score += 5.0;
    }

    // 5. Progression scaling:
    // As the stream nears the end, be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
